export const opovrgavanjeSearch: { slug: string; chunks: string[] }[] = [{"slug":"Aisa-i-Salim-Sablan","chunks":["Predaja na koju se pozivaju slaba je. Prenosi je Abdul Melik ibn Mervan ibn el Haris ed Devsi, nepoznata ličnost o kojoj u delima kritike i ocene prenosilaca nema pouzdanih podataka. Slabom su je ocenili i raniji i savremeni učenjaci. Uz to, izraz „sedela je preda mnom\" na arapskom jednostavno znači „sedela je ispred mene\", a ne ono što se u to učitava. Sadržaj primedbe Šije tvrde da je Aiša pokazivala svoje ruke, lice i glavu čoveku po imenu Salim Sablan, i za to navode sledeći hadis: Obavestio nas je Husejn ibn Hurejs, rekavši: obavestio nas je Fadl ibn Musa, od Džuajda ibn Abdur Rahmana, koji je rekao: obavestio me je Abdul Melik ibn Mervan ibn el Haris ibn Ebu","Zinab, koji je rekao: obavestio me je Ebu Abdullah Salim Sablan, koji je rekao: Aiša se divila njegovoj pouzdanosti i unajmljivala ga je. Pokazala mi je kako je Allahov Poslanik uzimao abdest: isprala je usta i nos tri puta, oprala lice tri puta, zatim desnu ruku tri puta i levu tri puta, stavila ruku na prednji deo glave, potom potrala glavu jednom do njenog zadnjeg dela, zatim prešla rukama preko ušiju i preko obraza. Salim je rekao: Dolazio sam joj kao rob, i nikada se od mene nije skrivala. Sedela bi ispred mene i razgovarala sa mnom, sve dok joj jednog dana nisam došao i rekao: Uputi dovu za mene, majko vernika. Rekla je: A šta je to? Rekao sam:","Da me Allah oslobodi. Rekla je: Neka te Allah blagoslovi. Zatim je spustila zastor preda mnom, i nakon tog dana je više nisam video. Odgovor na ovu primedbu Navedeni hadis je slab. Prenosilac koji ga prenosi jeste Abdul Melik ibn Mervan ibn el Haris ed Devsi, koji je nepoznata ličnost i o kojem u delima kritike i ocene prenosilaca nema pouzdanih podataka. Hadis je, dakle, slab i nikako nije dokaz protiv nas. Slabim su ga ocenili i raniji i savremeni učenjaci, a evo i dokaza za to: Izraz „sedela bi preda mnom\", koji se javlja u ovom slabom hadisu, na arapskom jeziku znači jednostavno „sedela bi ispred mene\". Izraz „bejne jedejje\" u delima arapskog jezika koristi se u značenju „ispred","mene\", pa ćete zato naći i mnoge hadise koji sadrže izraz „stao je preda mnom\", to jest ispred mene."]},{"slug":"Aisina-predaja-o-gusulu-i-hadis-o-obrezanju","chunks":["Šijska primedba pada na svakom nivou. Verzija sa dodatkom „To sam učinila ja i Allahov Poslanik, pa smo se okupali\" slabi zbog Velida ibn Muslima, poznatog po tedlisut tesviji. Sam propis prenosi se i bez tog dodatka, kroz više verodostojnih puteva, uključujući i Malikov Muvetta. Iste propise, istim izrazima, prenose i šijski nepogrešivi imami u El Kafiju, Vesailu š ši'a i Mir'atul ukulu, gde ih Medžlisi ocenjuje verodostojnim. Uz to, Kur'an izričito naređuje ženama Poslanika ﷺ da prenose mudrost koja se uči u njihovim kućama. Ovo je dvanaesti tekst u nizu koji pobija zablude o Aiši, majci vernika, radijallahu anha. Ovde se obrađuje primedba koja se odnosi na njeno prenošenje hadisa Ebu Musaa el Eš'arija o propisu gusula kada se","sastanu obrezani delovi, i na njene reči: „Naišao si na znalca.\" Hadis o kojem je reč Od Ebu Burde, od Ebu Musaa el Eš'arija, radijallahu anhu, koji je rekao: Skupina muhadžira i ensarija razišla se po tom pitanju. Ensarije su govorile da je gusul obavezan samo nakon izlaska sperme, dok su muhadžiri govorili da je, ako je došlo do sastajanja, gusul obavezan. Ebu Musa je rekao: Ja ću vam to razrešiti. Ustao sam i zatražio dozvolu da uđem kod Aiše, i ona mi je dozvolila. Rekao sam joj: Majko, ili: majko vernika, želim da te pitam o nečemu, ali me je stid. Rekla je: Nemoj se stideti da me pitaš o onome što bi pitao svoju majku koja te je","rodila, jer ja sam tvoja majka. Rekao sam: Šta iziskuje gusul? Rekla je: Naišao si na znalca. Allahov Poslanik ﷺ je rekao: Kada sedne između njena četiri uda i kada obrezani deo dotakne obrezani deo, gusul postaje obavezan. Izvor: Sahih Muslim, 349. Hadis je zabeležen i u Sunenu Tirmizije, sa verodostojnim senedom, preko Alije ibn Muhammeda i Abdur Rahmana ibn Ibrahima ed Dimeškija, od Velida ibn Muslima, od Evzaija, od Abdur Rahmana ibn el Kasima, od El Kasima ibn Muhammeda, od Aiše, žene Vjerovesnika ﷺ, koja je rekla: „Kada se obrezani deo sastane sa obrezanim delom, gusul postaje obavezan. To sam učinila ja i Allahov Poslanik, pa smo se okupali.\" Sened je ocenjen verodostojnim. Predaja je zabeležena i u Musnedu","imama Ahmeda, br. 25281, istim putem: Velid ibn Muslim, od Evzaija, od Abdur Rahmana ibn el Kasima, od njegovog oca, od Aiše, žene Vjerovesnika ﷺ. Šijska primedba Šijski prigovarač pita: šta znači „naišao si na znalca\"? Kako je Aiša Ebu Musau, radijallahu anhu, prenela pitanje o obrezanju? Zar su ashabi bili neuki u tim propisima? Da li je to takozvani udvorni govor? I šta je sa dodatkom iz Musneda, „To sam učinila ja i Allahov Poslanik, pa smo se okupali\" — zar to nije odavanje bračnih tajni? Prvo analiza seneda verzije iz Musneda Verzija koja sadrži dodatak „To sam učinila ja i Allahov Poslanik, pa smo se okupali\" prenosi se preko Velida ibn Muslima, a on je poznat po najtežem","obliku tedlisa, poznatom kao tedlisut tesvija. On bi iz Evzaijevog seneda izostavljao slabe prenosioce i prikazivao stvar tako kao da Evzai prenosi neposredno od pouzdanih autoriteta. Sam Evzai je prenosio i od slabih prenosilaca, pa bi ih Velid uklanjao i sened „izravnavao\", čineći da izgleda besprekorno. Ocene o Velidu ibn Muslimu zabeležene su u delu Mevsuatu akvalil imam Ahmed fi ridžalil hadis ve ilelihi, tom 4, str. 94, izdanje Alemul kutub, kao i u Mevsuatu akvalil imam ed Darekutni, tom 2, str. 700, Alemul kutub, Bejrut, prvo izdanje, 2001. Najizričitiji je zapis koji prenosi Salih ibn Muhammed el Esedi el Hafiz, zabeležen u Tehzibul kemalu: Čuo sam Hejsema ibn Haridžu kako kaže: Rekao sam Velidu ibn Muslimu: Ti si pokvario","Evzaijev hadis. Rekao je: Kako? Rekao sam: Ti prenosiš od Evzaija, od Nafija, i od Evzaija, od Zuhrija, i od Evzaija, od Jahjaa ibn Seida. A drugi između Evzaija i Nafija umeću Abdullaha ibn Amira el Eslemija, a između njega i Zuhrija Ibrahima ibn Murru, i Kurru, i druge. Pa šta te navodi da to pripisuješ neposredno? Rekao je: Ja Evzaija uzdižem iznad toga da prenosi od takvih. Rekao sam: A kada Evzai prenosi od takvih, a oni su slabi prenosioci, odbačene predaje, pa ih ti izostaviš i učiniš ih Evzaijevim prenošenjem od pouzdanih autoriteta, onda… Ali on nije obraćao pažnju na moje reči. Izvor: Tehzibul kemal fi esmair ridžal, El Mizzi, tom 31, str. 96 97, Muessesetur risala, prvo","izdanje. Isto potvrđuje i Darekutni: Velid ibn Muslim čini irsal. On prenosi od Evzaija hadise koje je Evzai preneo od slabih prenosilaca, od učenjaka koje je Evzai sreo, poput Nafija, Ataa i Zuhrija. On izostavlja imena slabih prenosilaca i pripisuje predaje Evzaiju od Ataa i Zuhrija, a reč je o takvima kao što su Abdullah ibn Amir el Eslemi i Ismail ibn Muslim. Izvor: Ed Duafa vel metrukin, Darekutni, br. 627; Tehzibul kemal. Zaključak je da upravo ta verzija predaje, ona koja sadrži dodatak „To sam učinila ja i Allahov Poslanik, pa smo se okupali\", pada u samom temelju, jer se u njenom senedu nalazi Velid ibn Muslim, koji je činio tedlis. Drugo kur'anska naredba ženama Poslanika ﷺ Što se","tiče samog sadržaja predaje, reč je o izričitoj kur'anskoj obavezi. Sura El Ahzab 33:34 I sećajte se Allahovih reči i mudrosti koja se kazuje u vašim domovima; Allah je, uistinu, dobar i sve u potpunosti zna. Prema tome, ako šerijatski interes iziskuje da se spomene ono što može delovati osetljivo, u tome nema ničega spornog i to je dozvoljeno. Ono što je zabranjeno jeste ono što pojedini ljudi čine radi ismevanja i ruganja. Štaviše, spominjanje propisa o čistoći pohvalno je delo, a ne ružno, nasuprot onome kako to prikazuju rafidije svojim napadima na ženu Poslanika ﷺ. Uzvišeni Allah kaže: Sura El Bekara 2:222 I pitaju te o mesečnom pranju! Reci: \"To je neprijatnost!\" Zato, nemojte da imate odnos sa ženama","za vreme mesečnog pranja, i ne prilazite im dok se ne očiste! A kada se očiste, onda im prilazite onako kako vam je Allah naredio! Allah, zaista, voli one koji se kaju i voli one koji se čiste. Treće predaja bez spornog dodatka Predaja je preneta i drugim putevima, bez dodatka „To sam učinila ja i Allahov Poslanik\". To je značajno jer pokazuje da je sam propis utvrđen nezavisno od spornog dodatka. U Muvetti imama Malika, u poglavlju o obaveznosti gusula kada se sastanu obrezani delovi, zabeleženo je sledeće: 142. Malik, od Ibn Šihaba, od Seida ibn el Musejjiba, da su Omer ibn el Hattab, Osman ibn Affan i Aiša, žena Vjerovesnika, govorili: Kada obrezani deo dotakne obrezani deo, gusul","postaje obavezan. 144. Malik, od Ebun Nadra, oslobođenog roba Omera ibn Ubejdullaha, od Seleme ibn Abdur Rahmana ibn Avfa, da je rekao: Pitao sam Aišu, ženu Vjerovesnika: Šta obavezuje gusul? Rekla je: Znaš li čemu si sličan, o Ebu Seleme? Poput petla koji čuje kokoš kako kokoće, pa i on kokoće s njom. Kada obrezani deo pređe obrezani deo, gusul postaje obavezan. 145. Malik, od Jahjaa ibn Seida, od Seida ibn el Musejjiba, da je Ebu Musa el Eš'ari došao Aiši, ženi Vjerovesnika ﷺ, i rekao joj: Veoma me je uznemirilo razilaženje ashaba Allahovog Poslanika po jednom pitanju, i teško mi je da to iznesem pred tebe. Rekla je: Šta je to? Ono o čemu bi pitao svoju majku, pitaj","mene o tome. Rekao je: Čovek opšti sa svojom ženom, pa klone i ne ejakulira. Rekla je: Kada obrezani deo pređe obrezani deo, gusul postaje obavezan. Ebu Musa el Eš'ari je rekao: Posle tebe o tome nikada nikoga neću pitati. 146. Malik, od Jahjaa ibn Seida, od Abdullaha ibn Ka'ba, oslobođenog roba Osmana ibn Affana, da je Mahmud ibn Lebid el Ensari pitao Zejda ibn Sabita o čoveku koji opšti sa svojom ženom, pa klone i ne ejakulira. Zejd je rekao: Neka se okupa. Mahmud mu je rekao: Ubejj ibn Ka'b nije smatrao gusul obaveznim. Zejd mu je rekao: Ubejj ibn Ka'b je od tog stava odustao pre nego što je umro. Izvor: Muvetta imama Malika, tom 2, str. 63,","tahkik El A'zami, Muessese Zajed ibn Sultan Al Nahjan, Abu Dabi, prvo izdanje, 1425. h. / 2004. Treba primetiti da ova predaja u Muvetti potvrđuje da je Aiša u pojedinim pitanjima bila učenija od nekih ashaba. A nesumnjivo je da su neki ashabi u drugim pitanjima bili učeniji od nje. Svaki ashab imao je svoje područje znanja. Četvrto isti propisi u šijskim izvorima Kada bi ono što je preneseno od Allahovog Poslanika ﷺ bilo sramota i nedostatak, kako to šije predstavljaju, onda Mejmuna i Umm Selema ne bi u šijskim knjigama prenele isto to od Allahovog Poslanika ﷺ, od njihovih nepogrešivih imama, u istim pitanjima i propisima. Niti bi njihov nepogrešivi imam to prenosio od Aiše, radijallahu anha, u propisima","o džunupluku i polucijama. Imam Rida prenosi od Aiše Preneseno je od Ebu Džafera, od Sa'da ibn Ismaila, od njegovog oca, koji je rekao: „Pitao sam Ebul Hasana er Ridaa, mir neka je na njega, o čoveku koji je postao džunup u ramazanu, pa je namerno spavao do jutra: šta je dužan?\" Odgovorio je da mu to ne škodi i da mu post ne kvari, pozivajući se na svog oca. Izvor: Vesailu š ši'a, El Amili, 10/59; Tehzibul ahkam, Tusi, 4/210; El Hadaikun nadira, Bahrani, 13/118. Nepogrešivi imam je, dakle, i sam prenosio od Aiše o pitanjima džunupluka između muža i žene, i tu predaju nije smatrao sramotnom niti udvornom, nego znanjem i razumevanjem. Propis koji Medžlisi ocenjuje verodostojnim Ais","ibn el Kasim pitao je Ebu Abdullaha, mir neka je na njega: „Mogu li muškarac i žena uzimati abdest iz iste posude?\" Odgovorio je: „Da, neka preliju vodu preko ruku pre nego što ruke stave u posudu.\" Izvor: Meladul ahjar, Medžlisi, tom 2, str. 234, ocenjeno verodostojnim. Izraz „obrezanje\" u šijskim predajama Isti izraz, hitan, odnosno obrezanje, koriste i njihovi nepogrešivi imami u njihovim sopstvenim knjigama, kako se prenosi od Alije, mir neka je na njega, i od imama Ridaa. Izvor: El Kafi, Kulejni, 3/46; Vesailu š ši'a, El Amili, 1/469; Muhtelefu š ši'a, Hilli, 1/321. Šta je Medžlisi zabeležio u Mir'atul ukulu U Mir'atul ukulu, u poglavlju „Šta obavezuje gusul muškarcu i ženi\", Medžlisi beleži više predaja: Druga predaja:","Skupina naših drugova, od Ahmeda ibn Muhammeda ibn Isaa, od Muhammeda ibn Ismaila, koji je rekao: Pitao sam Ridaa, mir neka je na njega, o čoveku koji opšti sa ženom bez ejakulacije: kada gusul postaje obavezan? Rekao je: Kada se obrezani deo sastane sa obrezanim delom, gusul postaje obavezan. Rekao sam: Sastajanje obrezanih delova jeste nestajanje glavića? Rekao je: Da. Treća predaja: Od Ahmeda ibn Muhammeda, od Hasana ibn Alije ibn Jaktina, od njegovog brata Alije ibn Jaktina, koji je rekao: Pitao sam Ebul Hasana, mir neka je na njega, o čoveku koji opšti sa robinjom, a ne ejakulira: da li se ona kupa? Rekao je: Kada obrezani deo padne na obrezani deo, gusul postaje obavezan, bila devica ili ne.","Izvor: Mir'atul ukul, Medžlisi, tom 13, str. 130 131 i 140, izdanje Darul kutubil islamijje. Medžlisi je sve navedene predaje ocenio verodostojnim. Šijski nepogrešivi imami, dakle, raspravljaju o potpuno istim intimnim propisima, koristeći potpuno iste izraze, u njihovim sopstvenim verodostojnim izvorima. Ako to kod Aiše predstavlja „odavanje intimnih tajni\", onda su po istom merilu njihovi imami jednako krivi. Peto Alijin stid zbog pitanja o mezju Nisu svi ashabi imali isti stepen znanja i razumevanja kao Aiša, radijallahu anha. Neki od njih nisu poznavali pojedine propise o čistoći, pa su nju o tome pitali. Čak ni Alija, radijallahu anhu, nije poznavao propis o mezju, o stvari koja se redovno dešava, i stideo se da o tome neposredno pita Poslanika ﷺ. Izvor:","Biharul envar, tom 77, str. 225; Mustedrekul vesail, Mirza Nuri, tom 1, str. 237; Tehzibul ahkam, Tusi, tom 1, str. 17 18; El Istibsar, Tusi, tom 1, str. 91. Ako sam imam Alija, koji je po šijskom merilu nepogrešiv, nije poznavao uobičajen propis o mezju i bilo mu je potrebno da neko drugi umesto njega pita Poslanika ﷺ, kako onda šije mogu kritikovati Aišu što je odgovorila na pitanje o čistoći koje joj je postavljeno? Šesto značenje reči „naišao si na znalca\" Značenje njenih reči jeste da je onaj ko pita došao znalcu propisa o dozvoljenom, uključujući i propise braka i onoga što iz njega proizlazi, i to na osnovu učenja Allahovog Poslanika ﷺ. Njeno znanje o propisima dozvoljenog preneseno","je neposredno od prvaka stvorenja, Muhammeda ﷺ, kroz ono što je od njega naučila u fikhu, znanju i sunnetu. Znanje preneseno od Allahovog Poslanika ﷺ jeste vrlina, čast i povlastica za onoga ko ga poseduje. Sedmo razlika između udvornog govora i prenošenja znanja Što se tiče optužbe da Aišina predaja predstavlja udvorni govor, treba znati da se udvornost, prema izjavama i tumačenjima svih sunijskih i šijskih učenjaka, odnosi na omekšavanje, razblaživanje i primamljivo doterivanje govora. Sam govor nije zabranjen, nego je zabranjeno govoriti na udvoran način. Aiša nije govorila udvorno, omekšano niti razblaženo. Ona je prenela šerijatski propis u njegovom jasnom i neposrednom obliku, tačno onako kako ga je Poslanik ﷺ izrekao. Reč hitan, odnosno obrezanje, nije vulgarna. To je","uobičajen izraz koji slušaocu jasno prenosi značenje i pojam. To je isti onaj izraz koji u šijskim knjigama i predajama koriste imam Alija, imam Rida i imam Džafer. Osmo ulazak Ebu Musaa kod Aiše Što se tiče ulaska Ebu Musaa el Eš'arija kod Aiše, radijallahu anhuma, da bi joj postavio pitanja, to se dogodilo nakon što je zatražio dozvolu. Svako ko je kod nje ulazio, a nije joj bio bliski rođak, činio je to zbog potrebe i tek nakon traženja dozvole, kao što je Ibn Abbas ulazio kod nje u njenoj poslednjoj bolesti nakon što je zatražio dozvolu. Dozvola ovde znači da se ona prethodno zaklonila i pokrila, u prisustvu svojih služavki. Deveto protivpitanje šijama Rafidija na kraju postavlja izazov:","„Da li biste prihvatili da vaša sestra izda takvu fetvu muškarcu, po uzoru na majku vernika?\" Pre odgovora, uzvraćamo istim pitanjem: da li biste prihvatili da vaša sestra izdaje verske propise muškarcu i da sledi ono što su Mejmuna i Umm Selema prenele muškarcima, i nepogrešivom imamu po vašem shvatanju, o čistoći nakon odnosa, o polucijama i o odnosu sa ženom u mesečnom pranju, i to u vašim knjigama i predajama? Što se tiče odgovora na njegovo pitanje, odgovor je potvrdan, ali pod dva uslova. 1. Da njeno prenošenje znanja bude neposredno od Allahovog Poslanika ﷺ, dakle od izvora zakonodavstva za čitav muslimanski ummet. Prikrivanje toga sprečilo bi prenošenje Poslanikovog znanja čitavoj zajednici. 2. Da bude žena Poslanika ﷺ, jer","je ženama Poslanika ﷺ, i nijednim drugim ženama, u Kur'anu izričito naređeno da čitavoj muslimanskoj zajednici prenesu sve znanje koje su videle ili naučile od Allahovog Poslanika ﷺ, bez izostavljanja, izvrtanja, iskrivljavanja ili prikrivanja. Ta naredba bila je posebna za njih, a ne za druge. Emulacija majki vernika od strane muslimanke odnosi se, dakle, na propise koji važe za sve muslimanke, a ne na propise koji su svojstveni majkama vernika, poput njihove udaje za Poslanika ﷺ uz više od četiri žene, ili njihove zabrane udaje nakon njegove smrti. Intimna pitanja između supružnika, kada potreba iziskuje njihovo iznošenje radi pojašnjenja šerijatskih propisa, dozvoljeno je spomenuti. Ali činiti to radi ismevanja i zabave zabranjeno je. To jasno pokazuju i sami šerijatski propisi:","Uzvišeni Allah u Svojoj Knjizi spominje mesečno pranje i dodirivanje žena, a sve to služi pojašnjenju propisa. Zaključak Šijska primedba pada na svakom nivou. 1. Verzija sa dodatkom „To sam učinila ja i Allahov Poslanik, pa smo se okupali\" oslabljena je dobro dokumentovanom praksom tedlisut tesvije Velida ibn Muslima, što potvrđuju Ahmed ibn Hanbel, Darekutni, Mizzi i brojni drugi autoriteti. 2. Sam propis, da je gusul obavezan kada se sastanu obrezani delovi, prenosi se kroz više verodostojnih puteva bez tog dodatka, uključujući i Muvettu imama Malika. 3. Iste propise, istim izrazima, prenose i šijski nepogrešivi imami u El Kafiju, Vesailu š ši'a i Mir'atul ukulu, gde ih Medžlisi ocenjuje verodostojnim. 4. Kur'an izričito naređuje ženama Poslanika ﷺ da prenose mudrost","koja se uči u njihovim kućama. 5. Sam imam Alija stideo se da Poslanika ﷺ pita o uobičajenom propisu o mezju, što pokazuje da svi ashabi nisu imali jednako znanje. Neka je Allah zadovoljan majkom vernika Aišom, koju je Allah očistio i oslobodio optužbe, i koja je uz drugarstvo sa Allahovim Poslanikom ﷺ imala i čast da mu bude žena i na ovom i na budućem svetu."]},{"slug":"Da-li-je-Ebu-Bekr-spalio-hadise","chunks":["Predaja na koju se šije pozivaju nije verodostojna, što izričito navode Zehebi u Tezkiretul huffazu, Kenzul ummal i El Envarul kašifa. Verodostojni izvori pokazuju upravo suprotno: Ebu Bekr je bio krajnje obazriv u sleđenju Poslanika ﷺ, primenjivao je sunnet, prenosio poslaničke propise, a sam Alija ibn Ebu Talib posvedočio je da je Ebu Bekr najbolji u ovom ummetu nakon Allahovog Poslanika ﷺ. Primedba Šije tvrde da je Ebu Bekr es Siddik, radijallahu anhu, spalio hadise Poslanika ﷺ zato što ih je bilo previše. Prvo predaja nije verodostojna Hadis koji navode nije verodostojan. Sken iz Tezkiretul huffaza prikazuje predaju pripisanu Aiši o tome da je Ebu Bekr spalio hadise, uz napomenu: „Ovo nije verodostojno, a Allah najbolje zna.\" Ovaj sken je","iz Kanz al umala ponavlja istu predaju o Ebu Bekru, neka je Allah zadovoljan njime, navodno kako je sakupljao hadise, proveo nemirnu noć, a potom zatražio od Aiše da mu donese zapisani materijal kako bi ga spalio. Naglašena napomena pri dnu navodi da se to pominje kod Ebu Bekra ibn Ebi Šejbe u njegovom Musnedu, ali da nije autentično, a Allah najbolje zna. Ovaj sken je važan jer pokazuje da izveštaj ne odbacuju tek kasniji polemičari; već sam izvorni materijal beleži slabost predaje. Sken iz El Envarul kašife kritički razmatra ovu predaju i navodi da ju je Zehebi ocenio neverodostojnom. Drugo Ebu Bekr je sledio Poslanika ﷺ i njegov sunnet U nastavku su svedočanstva da je Ebu Bekr, radijallahu anhu,","primenjivao ono što je Odabrani ﷺ govorio i činio, kao i priznanja Alije ibn Ebu Taliba, radijallahu anhu, da je najbolji u ovom ummetu nakon Poslanika ﷺ Ebu Bekr. Dokaz iz sakupljanja Kur'ana Sken iz Sahiha Buharije prikazuje Ebu Bekrov odgovor Omeru u vezi sa sakupljanjem Kur'ana: „Kako da učinim nešto što Allahov Poslanik ﷺ nije učinio?\" Ta izjava je ključna jer dokazuje krajnju Ebu Bekrovu obazrivost u sleđenju Poslanika ﷺ. On nije bio čovek koji bi olako odbacio, zanemario ili brisao poslaničku uputu. Naprotiv, njegov prvi poriv bio je da ne uvodi ništa novo osim ako to nije opravdano potrebom i prepoznato kao dobro. To izravno protivreči optužbi da je Ebu Bekr bio neprijateljski raspoložen prema Poslanikovim hadisima. Alijino","svedočanstvo da je Ebu Bekr sledio sunnet Sken iz Musneda imama Ahmeda sadrži predaju od Alije: Ebu Bekr je „postupao po postupku i sunnetu Allahovog Poslanika ﷺ\". To je presudno protiv same optužbe. Ako sam Alija svedoči da je Ebu Bekr sledio sunnet Poslanika ﷺ, onda se tvrdnja da je Ebu Bekr spaljivao hadise iz protivljenja sunnetu razotkriva kao polemika bez osnova. Alijino svedočanstvo da je Ebu Bekr najbolji nakon Poslanika ﷺ Sken iz Sahiha Buharije beleži kako Muhammed ibn el Hanefijja pita Aliju: „Ko je najbolji među ljudima nakon Allahovog Poslanika ﷺ?\" Alija je odgovorio: „Ebu Bekr.\" Ovim se pokazuje da je sam Alija otvoreno potvrđivao vrednost i položaj Ebu Bekra. Zato je nepošteno koristiti slabu predaju da bi","se Ebu Bekr prikazao kao pokvarena ličnost, a istovremeno zanemarivati verodostojna Alijina svedočanstva u kojima ga hvali. Ebu Bekr je primenjivao poslaničke propise o zekatu Sken iz Musneda imama Ahmeda spominje da je Ebu Bekr pisao o obavezama zekata koje je propisao Allahov Poslanik ﷺ. To je važno jer se vidi kako Ebu Bekr čuva, primenjuje i prenosi praktične pravne upute Poslanika ﷺ. To je suprotno od onoga što bi činio neko ko je navodno pokušavao da izbriše poslaničke hadise. Dodatno Alijino svedočanstvo o Ebu Bekru i Omeru Sken iz Musneda imama Ahmeda sa predajama od Alije u kojima navodi da su „najbolji u ovom ummetu nakon njegovog Vjerovesnika Ebu Bekr i Omer\". Ovaj dokaz je značajan jer pokazuje da","pohvala Ebu Bekru nije usamljena u jednoj predaji. Svedočanstvo se ponavlja, i dolazi od samog Alije. Time se polemički pokušaj da se slaba predaja upotrebi protiv Ebu Bekra ruši pred verodostojnim i ponovljenim predajama koje potvrđuju njegovu vrednost i njegovo sleđenje poslaničkog puta. Zaključak Verodostojni i jači dokazi upućuju u suprotnom smeru. Ebu Bekr, radijallahu anhu, bio je krajnje obazriv u sleđenju Poslanika ﷺ, primenjivao je sunnet, prenosio poslaničke propise, a Alija ibn Ebu Talib, radijallahu anhu, hvalio ga je kao najboljeg u ovom ummetu nakon Allahovog Poslanika ﷺ. Optužba, dakle, nije samo slaba, nego joj protivreče i istorijski i hadiski dokazi."]},{"slug":"Da-li-je-Omer-pobegao-sa-Uhuda","chunks":["Predaja iz Taberijevog tefsira, na koju se šije pozivaju, slaba je jer se u njenom senedu nalazi Ebu Hišam er Rifai, kojeg su oslabili Buhari, Ibn Hadžer, Nesai, Ibn el Dževzi, Ibn Ebu Hatim, Ibn Adijj i Albani. Čak i kada bi se pretpostavilo da je verodostojna, Allah na kraju samog ajeta kaže da im je već oprostio, a po šijskom El Kafiju bekstvo pred trojicom uopšte se i ne smatra bekstvom. Mnoge šije koriste predaju iz Taberijevog tefsira u kojoj Omer, radijallahu anhu, uči ajet u kojem Uzvišeni Allah kaže: Sura Ali Imran 3:155 One od vas koji su uzmakli na dan kada su se dve grupe sukobile, zaista je đavo naveo da posrnu zbog nečeg od onoga što","su pre zgrešili. A Allah im je već oprostio, Allah, zaista, grehe oprašta i ne žuri sa kaznom. Nakon učenja tog ajeta, Omer, radijallahu anhu, naveo je da je i on bio među onima koji su se povukli na Uhudu. Šije naročito vole da se hvataju za deo u kojem Omer sebe upoređuje sa divokozom dok se povlačio. Prvo predaja je slaba zbog Ebu Hišama er Rifaija Ova predaja je slaba jer njen sened sadrži prenosioca po imenu Ebu Hišam er Rifai, kojeg je oslabila većina učenjaka. Imam Buhari Imam Tirmizi preneo je predaju koja u svom senedu sadrži Ebu Hišama er Rifaija, pa je o tom prenosiocu pitao svog učitelja, imama Buharija, a on je Ebu Hišama er Rifaija","oslabio. Izvor: El Ilelul kubra, str. 172. Imam Ibn Hadžer el Askalani Ebu Hišam er Rifai nije jak u hadisu, on je iz mlađih desete generacije… Buhari je rekao da postoji saglasnost o njegovoj slabosti. Izvor: Takribut tehzib, str. 909. Imam Nesai Nesai ga navodi u svom delu o slabim i odbačenim prenosiocima, kao „Muhammed ibn Jezid Ebu Hišam er Rifai\". Izvor: Ed Duafa vel metrukin, Nesai, str. 223. Ibn el Dževzi Ebu Hišam er Rifai… Buhari je rekao da među učenjacima postoji saglasnost da je slab. Nesai i Razi rekli su da je slab. Izvor: Ed Duafa vel metrukin, Ibn el Dževzi, tom 3, str. 107. Ibn Ebu Hatim er Razi Čuo sam svog oca kako kaže da je","Ebu Nuajm upitan o Ebu Hišamu er Rifaiju, pa je rekao da je bio najslabiji u traženju znanja i najčudniji od svih. A preneo nam je Abdur Rahman, koji je rekao: Pitao sam svog oca o Ebu Hišamu er Rifaiju, pa je rekao: Slab je. Izvor: El Džerh vet ta'dil, Ibn Ebu Hatim er Razi, tom 8, str. 129. Ibn Adijj Neki hadisi Ebu Hišama er Rifaija, koje je preneo od Ebu Bekra ibn Ajjaša, Ibn Idrisa i drugih kufanskih učenjaka, proglašeni su munker predajama. Izvor: El Kamil fid duafa, tom 7, str. 529. Prema Ibn Adijju, dakle, predaje Ebu Hišama er Rifaija od Ebu Bekra ibn Ajjaša spadaju u munker kategoriju, što znači da su slabe. A kada pogledamo","predaju u Taberijevom tefsiru, vidimo da Ebu Hišam prenosi upravo od Ebu Bekra ibn Ajjaša. Nasirudin el Albani Albani je u svojoj zbirci slabih hadisa naveo niz predaja Ebu Hišama er Rifaija i sve ih oslabio, izričito navodeći da je Ebu Hišam er Rifai slab. Drugo odgovor na njihove pokušaje da ojačaju prenosioca Zehebijevo delo o kritikovanim, a pouzdanim prenosiocima Imam Zehebi ima delo pod naslovom „Onaj ko je kritikovan, a pouzdan je\". U toj knjizi naveo je niz prenosilaca koje su veliki učenjaci oslabili i kritikovali, ali su, prema Zehebiju, pouzdani. Šije će tvrditi da, ako ga je imam Zehebi naveo u toj knjizi, onda mora biti pouzdan. To je, međutim, njihova zabluda, jer to samo znači da Zehebi","o Ebu Hišamu er Rifaiju ima mišljenje koje se razlikuje od mišljenja ostalih učenjaka. Uz to, priređivač te knjige, Abdullah ibn Dajfullah er Ruhajli, u svom uvodu navodi da u knjizi ima slučajeva u kojima je Zehebi spomenuo nekoga ko zapravo treba da bude ocenjen slabim. Isti priređivač u fusnoti pod kojom se spominje Ebu Hišam kaže: „Zaključno, on je slabog pamćenja.\" Tvrdnja da ga je Muslim spomenuo u svom Sahihu Drugi argument koji koriste jeste da ga je imam Muslim spomenuo u svom Sahihu. Iz neznanja ne shvataju da bi imam Muslim ponekad naveo slab sened čiji je hadis, odnosno metn, verodostojan zato što ga podupire drugi verodostojan sened. Ima slučajeva u kojima imam Muslim navodi niz hadisa istog","teksta, a različitih seneda, pa na kraju poglavlja uvrsti i slabe senede kao svedoke za verodostojne. To je imam Muslim i sam naveo u svom uvodu. Isto je rekao i imam Nevevi u svom komentaru Sahiha Muslima. On navodi da bi imam Muslim na početku poglavlja spomenuo samo verodostojne senede kao temelj, a zatim isti hadis sa slabim senedom kao svedoka za prve predaje. Imam Ibn Salah rekao je isto u svom poznatom delu Ulumul hadis, str. 84: ima slučajeva u kojima učenjaci navode hadis sa slabim senedom kao svedočanstvo za isti hadis sa drugim, verodostojnim senedom. I naveo je da toga ima kod Buharije i Muslima. Na primer, imam Muslim naveo je hadis sa senedom koji sadrži prenosioca po","imenu Mudžalid, koji je slab. Imam Nevevi to je objasnio rekavši da je reč o mutabei ili šahidu, gde sened može sadržati slabog prenosioca da bi ojačao senede pre njega. Tvrdnja o popustljivosti u tefsiru Poslednji argument kojim pokušavaju da ojačaju ovaj hadis jeste izjava Ebu Seida el Kattana: „Oni, dakle učenjaci, uzimali su tefsir od onih kojima se u hadisu ne veruje.\" Šije odmah misle da je to propusnica i da to moramo prihvatiti. Ne shvataju da ta izjava, iako je ispravna, ne znači da je primenjujemo uvek. Šijski učenjak Muhammed Ali Esedi rekao je: „Sunnet objašnjava Kur'an, pa ga zato treba preispitivati. Ne možemo odbaciti sve predaje tefsira, niti možemo sve prihvatiti.\" Postoji i mnoštvo primera u kojima","su sunijski učenjaci oslabili predaje tefsira u svojim sopstvenim tefsirima. Imam Ibn Kesir to je učinio mnogo puta u svom Tefsiru. Isto tako je i imam Sujuti oslabio pojedine predaje u svom Durrul mensuru, kao i Ibn Ebu Hatim. Učenjak Salim el Hilali oslabio je upravo predaju Ebu Hišama er Rifaija o Omeru u svom delu El Istiab fi esbabin nuzul, tom 1, str. 317. Kada učenjaci kažu da u tefsiru možemo biti popustljivi prema slabim hadisima, to znači da prihvatamo one koji nose značenje koje je opravdano upotrebiti u tumačenju Kur'ana. To se ne može primeniti na hadis Ebu Hišama, jer on nema takvo značenje. On ne nudi nikakvo posebno tumačenje u smislu objašnjenja smisla ajeta. U tom slučaju,","dakle, nema popustljivosti. Ova predaja Ebu Hišama može se smatrati i istorijskom predajom, jer govori o Bici na Uhudu i o onome što se tada dogodilo. A istorijske predaje moraju se strogo ispitivati, kako navodi šejh Osman el Hamis u svom delu Hukba minet tarih, str. 18 24. Treće ismevanje poređenja sa divokozom Šije vole i da se rugaju Omeru, radijallahu anhu, zato što je sebe uporedio sa divokozom. Hoće li se, međutim, smejati kada saznaju da je u njihovoj verziji imam Alija, radijallahu anhu, upoređen sa svezanom devom prilikom davanja prisege Ebu Bekru, radijallahu anhu? Četvrto i kada bismo pretpostavili da je predaja verodostojna Čak i kada bismo pretpostavili da je predaja verodostojna i da je Omer, radijallahu anhu,","zaista pobegao iz bitke, odgovaramo sledećim: 1. Allah je na kraju samog ajeta rekao: „A Allah im je već oprostio.\" 2. Muhammed ibn Jakub el Kulejni prenosi svojim senedom od Ebu Abdullaha, mir neka je na njega, koji je rekao: Ko pobegne od dvojice u bici, taj je pobegao. A ko pobegne od trojice, taj nije pobegao. Izvor: El Kafi, Kulejni, tom 5, str. 34, hadis 1."]},{"slug":"Da-li-je-Omer-rekao-da-Poslanik-bunca","chunks":["Reč ehedžere ni u jednoj predaji nije pripisana Omeru. Svi lanci od njega beleže samo izjavu o bolu i reči da nam je dovoljna Allahova Knjiga. Ispravno pročitana, ta reč u upitnom obliku poriče buncanje, a ne potvrđuje ga. Omerov stav bio je idžtihad, a Poslanikovo ﷺ ćutanje na njega ima snagu odobravanja. Da je pisanje bilo naređeno objavom, ni neslaganje ni bol ne bi ga sprečili, jer je Poslanik ﷺ nakon toga živeo još danima i usmeno prenosio upute. Hadis o kojem je reč Ibn Abbas je govorio: Najveća nesreća je ona koja je sprečila Allahovog Poslanika ﷺ da im napiše onu knjigu, zbog njihovog neslaganja i galame. Izvor: Sahih Buhari i Sahih Muslim. Primedba Tvrdi se da je","Omer ibn el Hattab rekao da Allahov Poslanik bunca, i to njemu u lice; da je okupio svoje pristalice kako bi sprečio Poslanika ﷺ da napiše oporuku kojom Aliju ibn Ebu Taliba određuje za naslednika; te da su njegove reči „Dovoljna nam je Allahova Knjiga\" bile odbacivanje sunneta. Odgovor Prvo reč ehedžere nikada nije pripisana Omeru Tvrdnja da je Omer izgovorio reč ehedžere nema oslonca ni u jednom lancu prenošenja. Sve predaje od Omera beleže isključivo: Omer je rekao: Allahovog Poslanika ﷺ savladala je bol, a vi imate Kur'an. Dovoljna nam je Allahova Knjiga. Reč ehedžere javlja se u pojedinim predajama kao reč neodređene skupine prisutnih, bez navođenja Omera kao njenog izvora. Pripisivanje te reči Omeru postoji isključivo u šijskoj","polemičkoj literaturi. Drugo šta ta reč zaista znači Postoje tri jezička čitanja te reči. 1. Upitno čitanje , kojem se daje prednost. Ono buncanje poriče kod Poslanika ﷺ, a ne potvrđuje ga. 2. Obraćanje onima koji su se sporili. Pojedini učenjaci to čitaju kao obraćanje onima koji su se prepirali pred Poslanikom ﷺ, čime se opisuje njihovo ponašanje, a ne njegovo stanje. 3. Vezivanje za Omerove reči. Ako se tumači kao izveštaj o stanju Poslanika ﷺ, raniji učenjaci to vezuju za ono što je Omer rekao o savladanosti bolom, a ne za nesuvislost govora. Učenjaci su saglasni da se el hedžr, u značenju nesuvislog ili neprimerenog govora, ne može ispravno pripisati Poslaniku ﷺ, koji je bio sačuvan i u zdravlju","i u bolesti. Sura En Nedžm 53:3 4 On ne govori po hiru svome. To je samo objava koja mu se obznanjuje. Treće Omerov stav bio je idžtihad Imam el Mazari kaže: Ashabima je bilo dozvoljeno da se raziđu u vezi sa pisanjem, uprkos izričitoj naredbi, jer naredbe mogu biti popraćene naznakama koje ih prevode iz obaveznosti u nešto drugo. Imam Kurtubi kaže: Razilaženje ashaba u vezi sa ovim dokumentom slično je njihovom razilaženju u vezi sa njegovim ﷺ rečima: Neka niko ne klanja ikindiju osim kod Benu Kurejza. Najjači dokaz koji ide u prilog Omerovom stavu jeste samo ćutanje Poslanika ﷺ. U islamskoj pravnoj teoriji, poslaničko ćutanje ima snagu odobravanja. Da je Omer prekoračio meru ili se suprotstavio božanskoj","obavezi, Poslanik ﷺ bi ga prekorio. Poslanik ﷺ je nakon toga živeo još danima i usmeno prenosio upute. Da je pisanje bilo naređeno objavom, ne bi ga napustio zbog neslaganja. Sura El Maida 5:67 O Poslaniče, kazuj ono što ti se objavljuje od Gospodara tvoga, a ako to ne učiniš, onda nisi dostavio poslanicu Njegovu. Četvrto reči „Dovoljna nam je Allahova Knjiga\" nisu odbacivanje sunneta Omerova izjava bila je procena vezana za okolnosti, zasnovana na njegovom čitanju situacije, da je ono što je Poslanik ﷺ nameravao da napiše već obuhvaćeno postojećom uputom. Sura El En'am 6:38 U Knjizi Mi nismo ništa izostavili. Omer je video da Poslanika ﷺ savladava jaka bol, a da ashabi već poseduju i Kur'an i utvrđeni","sunnet. Vrata učenjačkog idžtihada ostala su otvorena. Njegova namera bila je da olakša Poslanikov teret, a ne da ušutka objavu. Peto tvrdnja o Alijinom određenju obara se samim hadisom Tvrdnja da je Omer sprečio Poslanika ﷺ da napiše oporuku kojom Aliju ibn Ebu Taliba određuje za halifu obara se samim tim hadisom. Poslanik ﷺ je dao usmene upute: da se mnogobošci proteraju sa Arapskog poluostrva i da se poštuju izaslanstva. O nasleđivanju je ćutao, ili to prenosilac nije zapamtio. Da je Alijino određenje bilo obaveza od Allaha, Poslanik ﷺ bi ga preneo usmeno, jer je nakon toga živeo još danima i neprestano govorio. Njegovo ćutanje o tome je presudno. O tuzi Ibn Abbasa Izjava Ibn Abbasa da je taj događaj","bio „najveća nesreća\" ne protivreči ispravnosti Omerovog postupka. Ibn Abbas, učenjak ovog ummeta, žalio je zbog onoga što je propušteno u pogledu izričitog pisanog pojašnjenja. Žalio je zbog onoga što je moglo biti, a ne zato što je Omer zgrešio. Zaključak Napad na Omera ibn el Hattaba u vezi sa događajem u četvrtak pada u celosti. Reč ehedžere ni u jednoj predaji nije pripisana Omeru, jer svi lanci beleže samo njegovu izjavu o bolu. Ispravno pročitana, ta reč poriče buncanje, a ne potvrđuje ga. Omerov stav bio je zakonito učenjačko rasuđivanje, koje je odobreno poslaničkim ćutanjem. Pisanje nije bilo naređeno objavom, jer da jeste, ni neslaganje ni bol ne bi sprečili njegovo izvršenje. Sačuvanost Poslanika ﷺ u razumu, govoru i","prenošenju objave, i u zdravlju i u bolesti, ostaje utvrđena."]},{"slug":"Da-li-se-Aisa-kupala-pred-dvojicom-ljudi","chunks":["Sam tekst hadisa obara primedbu. U svim verzijama izričito stoji da je između njih bio zastor. Prvi čovek bio je njen brat, po krvi ili po mleku, a drugi Ebu Seleme, koji je tada bio dečak pre punoletstva. Pitanje se nije ticalo načina kupanja, nego količine vode, na šta ukazuje traženje posude od jednog sa'a. Uz to, u šijskim knjigama Mejmuna prenosi isto takvo pitanje, a njihovi izvori navode i da je Fatima odgovarala muškarcima na verska pitanja. Primedba Pričao mi je Abdullah ibn Muhammed, pričao nam je Abdus Samed, pričao nam je Šu'be, pričao mi je Ebu Bekr ibn Hafs, koji je čuo Ebu Selemu kako kaže: Ušli smo kod Aiše, ja i njen brat, i njen brat ju","je pitao o kupanju Allahovog Poslanika ﷺ. Zatražila je posudu od otprilike jednog sa'a i okupala se, prelivajući vodu preko svoje glave, a između nas i nje bio je zastor. Izvor: Sahih Buhari, 249. Ista predaja spominje se i u Sahihu Muslima, uz neznatnu razliku u reči za zastor. Te hadise koriste pojedine rafidije, među njima i njihov fanatični prvak Jasir el Habib, tvrdeći da je Aiša puštala strane ljude da uđu kod nje, a da bi se potom pred njima kupala. Ostale verzije predaje Muslimova predaja: „Žene Vjerovesnika ﷺ skraćivale su kosu tako da je bila poput kruga oko glave.\" Ahmedov Musned: „Ušli smo kod Aiše, ja i njen brat po mleku, i njen brat ju je pitao o","kupanju Allahovog Poslanika ﷺ. Zatražila je posudu od otprilike jednog sa'a, okupala se i prelila vodu preko glave tri puta, a između nas i nje bio je zastor.\" Nesaijeva predaja: „Ušao sam kod Aiše, radijallahu anha, ja i njen brat po mleku, pa ju je pitao o kupanju Vjerovesnika. Zatražila je posudu sa vodom od otprilike jednog sa'a, zaklonila se zastorom, okupala se i prelila vodu preko glave tri puta.\" Prvo ko su ta dvojica? Prvi čovek Aišin brat Buhari i drugi prenose da je reč o njenom bratu, bez pobližeg određenja. Davudi u svom komentaru Buharije smatra da je to Abdur Rahman ibn Ebu Bekr es Siddik. Rečeno je i da je to njen brat po majci, Tufejl ibn","Abdullah. Hafiz Ibn Hadžer u Fethu kaže: „Nijedno od toga nije ispravno, jer je Muslim preneo putem Muaza, Nesai putem Halida ibn el Harisa, a Ebu Avana putem Jezida ibn Haruna, svi od Šu'beta, u ovom hadisu, da je reč o njenom bratu po mleku.\" Muslim i drugi prenose da je to njen brat po mleku. Nevevi i skupina učenjaka smatraju da je to bio Abdullah ibn Jezid el Basri, a drugi da je to njen brat po mleku Ebu Seid Kesir ibn Ubejd el Kufi. Zaključak je da je prvi čovek njen brat, bilo po krvi bilo po mleku. Tvrdnja da je to naknadno krpljenje pravnika nema osnova, jer Muslimov hadis doslovno navodi da je bio njen brat po","mleku, što je unutrašnji dokaz u samom tekstu. Drugi čovek Ebu Seleme ibn Abdur Rahman ibn Avf Pojedini komentatori tvrdili su da je Ebu Seleme bio Aišin bratić po mleku i da ga je dojila Umm Kulsum bint Ebu Bekr. Drugi su tvrdili da joj je bio bratić po krvi. Međutim, kod Muslima je zabeleženo da je Ebu Seleme rekao: „Žene Vjerovesnika ﷺ skraćivale su kosu tako da je bila poput grive.\" To znači da je Ebu Seleme video kosu žena Poslanika ﷺ, a ne samo Aiše. Da je bio mahrem isključivo Aiši, kako bi video kosu ostalih žena? Ibn Redžeb el Hanbeli u Fethul bariju kaže: „Čini se da je Ebu Seleme tada bio mali i da nije bio","dostigao punoletstvo, a onaj drugi bio je njen brat po mleku.\" Najispravnije je mišljenje da je Ebu Seleme tada bio dečak, mlađi od dvanaest godina. To znači da se događaj zbio pre 44. godine po Hidžri. Aiša je umrla 58. godine po Hidžri. Drugo nijedan deo tela nije bio otkriven Zastor je izričito spomenut u svim verzijama. 1. Muslimova predaja: „a između nas i nje bio je zastor\". 2. Buharijeva i Ahmedova predaja: „a između nas i nje bio je zastor\". 3. Nesaijeva predaja: „zaklonila se zastorom\". Značenje reči hidžab Iz reči Uzvišenog Allaha ne razume se da bi neki deo njenog tela bio otkriven: Sura El Ahzab 33:53 A kada od njih nešto tražite, tražite to od njih iza","zastora. To je čistije i za vaša i za njihova srca. Kur'an je razlog zastora protumačio čistoćom srca, dakle zastorom pogleda uopšte. Zavesa potpuno sprečava pogled i nije prozirna, kako to pokušavaju da prikažu pojedine rafidije. A spominjanje kose? To je dokaz da je Ebu Seleme, dok je bio dečak, video Aišinu kosu i kosu ostalih žena u nekoj drugoj prilici, a ne u ovoj. Ono što je rekao samo je dodatak koji ukazuje na to da kratka kosa ne iziskuje veliku količinu vode prilikom kupanja. Treće o čemu su zapravo pitali? Pitanje se ticalo količine vode, a ne načina kupanja. Dokaz za to jesu reči „zatražila je posudu od jednog sa'a\", što pokazuje da su pitali o količini. Ajni","kaže: „To jest, ovo je poglavlje koje pojašnjava propis kupanja vodom u količini jednog sa'a, jer je sa' naziv za drvenu posudu, pa se kupanje njome ne može ni zamisliti.\" Zato je imam Buhari ovaj hadis naslovio: „Poglavlje o kupanju sa jednim sa'om i sličnom količinom.\" Imam Nesai naslovio ga je: „Poglavlje o spominjanju količine vode koja je čoveku dovoljna.\" Odgovor onima koji prigovaraju Odgovor je jednostavan: žene Poslanika ﷺ najbolje su poznavale način na koji se on kupao. Aiša je upravo to i opisala. Uzvišeni Allah kaže: Sura El Ahzab 33:21 Vi u Allahovom Poslaniku imate divan uzor. To znači da je reč o Božijoj naredbi upućenoj njima, i da su one to poznavale bolje od bilo kojeg ashaba","ili muškarca tog vremena. Četvrto poučavanje iza zastora Aiša je na sebi ostavila odeću na onom delu tela u koji ni mahremu nije dozvoljeno da gleda, i vodu je prelivala preko odeće, jer to nije činila radi obaveznog kupanja, nego radi poučavanja. Nije htela da pouči da učenik mora gledati u telo učitelja, nego da pokaže kako se taj jedan sa' vode raspoređuje po delovima tela, gornjim i donjim. Svaki put bi uzimala određenu količinu vode iz tog sa'a i spominjala mesta preko kojih voda prelazi, i to iza zastora. Njen brat je mogao videti jedino kako se voda u posudi smanjuje i čuti opis kupanja, i ništa više od toga. Peto primedba na reči kadije Ijada Reči kadije Ijada","u delu El Mu'lim treba razumeti tako da su oni koji su pitali gledali u njenu glavu i gornje delove tela dok je bila obučena, jer se propis o gledanju muškarca u telo svojih mahrema razlikuje od propisa o stranoj ženi. Iako je to njegov trud u tumačenju hadisa, malo je verovatno da je Ebu Seleme bio sin po mleku Umm Kulsum, zbog njihove bliske dobi. Ispravnije je da se događaj zbio dok je Ebu Seleme bio dečak koji nije dostigao punoletstvo. Kurtubijeve reči Ibn Redžeb el Hanbeli u Fethul bariju, komentarišući Kurtubijeve reči, kaže: „Tvrdnja da je Ebu Seleme bio njen bratić po krvi očigledna je greška, jer je Ebu Seleme sin Abdur Rahmana ibn Ebu Bekra el Kasim.","Čini se da je Ebu Seleme tada bio mali i da nije dostigao punoletstvo, a onaj drugi bio je njen brat po mleku.\" Jasan tekst obara nagađanje. Kod Buharije stoji „a između nas i nje bio je zastor\", a kod Muslima „zastor\". Ne zna se odakle im mogućnost da zastor odrede za jedno mesto na telu, a ne za drugo. Aiša je zaklonila donje delove tela upravo zato da se, kada prelije vodu preko odeće, odeća ne bi priljubila uz telo. Šesto svedočanstva o Aišinoj stidljivosti Poslanik ﷺ je doslovno rekao: „Nemojte me uznemiravati u vezi sa Aišom.\" Ulazila sam u svoju kuću u kojoj su ukopani Allahov Poslanik i moj otac, pa bih skidala odeću sa sebe govoreći: to","su samo moj muž i moj otac. A kada je sa njima ukopan i Omer, tako mi Allaha, u nju nisam ulazila osim čvrsto zaogrnuta odećom, iz stida pred Omerom. Izvor: Musned imama Ahmeda. Allahov Poslanik je rekao: Bićete proživljeni bosi, goli i neobrezani. Rekla sam: Allahov Poslaniče, hoće li muškarci i žene gledati jedni u druge? Rekao je: Stvar će biti preozbiljna da bi ih to zanimalo. Izvor: Sahih Buhari, 6527. Sedmo ono što stoji u njihovim knjigama U knjizi Vesailu š ši'a, tom 2, str. 244, stoji: Od Mejmune, koja je rekla: Ja i Allahov Poslanik ﷺ postali smo džunup, pa sam se okupala iz posude, a u njoj je ostalo nešto vode. Zatim je došao Allahov Poslanik","i okupao se iz nje. Rekla sam: Allahov Poslaniče, to je ostatak od mene. Rekao je: Voda nije nečista. Izvor: Vesailu š ši'a, tom 2, str. 244. A o Fatimi u njihovim knjigama stoji: Iz ove i drugih predaja imamo korist da se ona, istinoljubiva, susretala sa muškarcima i odgovarala na njihova pitanja i njihove pravne upite, ili im držala poneke verske pouke. Da li je to njima dozvoljeno, radijallahu anhum, a Aiši, radijallahu anha, nije?"]},{"slug":"Dogadaj-sa-perom-i-papirom","chunks":["Omer, radijallahu anhu, nije uvredio Poslanika ﷺ. Jedina njegova izjava jeste da je Poslanik ﷺ teško bolestan, a to nije uvreda nego briga. Reči „Zar bunca?\" nisu izgovorili ni Omer ni oni koji su se s njim složili, nego druga skupina, i to u obliku pitanja prekora. Pisanje tog papira bilo je pohvalno, a ne obavezno, jer bi ga Poslanik ﷺ inače napisao u danima koji su usledili. Omer nije odbacio sunnet, jer je preneo 539 hadisa, a sam Alija u Nehdžul belagi kaže da je Knjiga dovoljan dokaz. Tvrdnja Šije kažu: Allahov Poslanik ﷺ, koji je bio na samrtnoj postelji, zatražio je pero i papir i rekao: „Napisaću vam nešto što vas neće dati da zalutate nakon mene.\" Omer","ibn el Hattab se usprotivio i rekao: „Poslanik ﷺ bunca, a dovoljna nam je Allahova Knjiga.\" Nekoliko je tačaka koje treba razmotriti: 1. Da li je Omer, radijallahu anhu, zaista uvredio Poslanika ﷺ? 2. Da li su sunije u zabludi, budući da Poslanik ﷺ nije napisao dokument koji čuva od zablude? 3. Da li je Omer, radijallahu anhu, odbacio sunnet? 4. Zašto je Poslanik ﷺ rekao ashabima da izađu i napuste njegovu kuću? Prvo tvrdnja o uvredi je neistinita Tvrdnja da je Omer, radijallahu anhu, uvredio Poslanika ﷺ neistinita je i za nju nema dokaza. Jedina izjava koja se od Omera prenosi glasi: „Poslanika ﷺ je savladala bol.\" A to očigledno nije uvreda, nego navođenje činjenice da Poslanik ﷺ trpi","bol i da nema snage da taj dokument napiše. Isto je i sa odbijanjem Alije, radijallahu anhu, kada mu je Poslanik ﷺ naredio da izbriše naziv „Allahov Poslanik\" pored njegovog imena prilikom sporazuma na Hudejbiji. Ako šije tvrde da je Alija, radijallahu anhu, odbio da izbriše naziv „Allahov Poslanik\" iz poštovanja i uvažavanja prema Allahovom Poslaniku ﷺ, onda kažemo da je i Omer, radijallahu anhu, odbio da donese pero i papir iz brige za Poslanika ﷺ, koji je bio teško bolestan. Što se tiče tvrdnje da je Omer optužio Poslanika ﷺ da bunca, ni to nije tačno. To nisu izgovorili ni Omer ni oni koji su se s njim složili u tom događaju, nego druga skupina, i to u obliku","pitanja prekora. Drugim rečima, oni su time hteli reći: „Zašto mu ne date pero i papir, zar mislite da bunca?\" Tako je to protumačio imam Ebul Abbas el Kurtubi u svom komentaru Sahiha Muslima, i rekao je da je to najbolje objašnjenje. Ibn Hadžer el Askalani dao je prednost drugom objašnjenju, rekavši da je onaj ko je rekao „Zar bunca?\" bio skoro primio islam i nije bio svestan da takve bolesti ne mogu uticati na reči Poslanika ﷺ. Drugo da li su sunije u zabludi? Ako neko tvrdi da su sunije u zabludi zato što oporuka koju je Poslanik ﷺ hteo da napiše nije napisana zbog Omera, kažemo da je papir koji je Poslanik ﷺ hteo da napiše bio mustehab,","a ne vadžib. Ono što je u našoj veri pohvalno ima za cilj da nas uputi, ali nam nije zajamčeno da ćemo zalutati ako po tome ne postupimo. Isto važi i za papir koji je Allahov Poslanik ﷺ nameravao da napiše, a dokaz za to jeste činjenica da ga on ﷺ nije napisao ni u preostalim danima svog života pre preseljenja. Da je pisanje tog papira bilo obavezno za Poslanika ﷺ, on bi ga napisao, bez obzira na to da li se Omer, radijallahu anhu, s tim slagao ili ne. Sura El Maida 5:67 O Poslaniče, kazuj ono što ti se objavljuje od Gospodara tvoga, a ako to ne učiniš, onda nisi dostavio poslanicu Njegovu. Treće da li je Omer","odbacio sunnet? Neko bi mogao pomisliti da je Omer, radijallahu anhu, odbacio sunnet kada je rekao: „Dovoljan nam je Kur'an.\" Ta tvrdnja je neistinita iz sledećih razloga. 1. Omer, radijallahu anhu, preneo je 539 hadisa. Da li bi neko ko odbacuje sunnet preneo sve te predaje? 2. Omer, radijallahu anhu, jednom je rekao: „Čuvajte se ljudi mišljenja, jer su oni neprijatelji sunneta.\" 3. U drugoj izjavi rekao je: „Sudi po onome što je u Allahovoj Knjizi. A ako presudu ne nađeš u Allahovoj Knjizi, onda sudi po onome što je u sunnetu Allahovog Poslanika ﷺ.\" 4. Postoji i verodostojna predaja u kojoj Omer, radijallahu anhu, ljubi crni kamen i kaže da to čini samo zato što je video Poslanika ﷺ","da to čini. To jasno pokazuje da je sledio sunnet. 5. Sam Alija ibn Ebu Talib, radijallahu anhu, rekao je u Nehdžul belagi: „Knjiga je dovoljan dokaz i argument.\" Da li je, dakle, imam Alija, radijallahu anhu, odbacio sunnet time što je rekao da je Kur'an dovoljan kao dokaz i argument? Četvrto Poslanikova oporuka bila je Kur'an Kada je Omer ibn el Hattab rekao „Dovoljan nam je Kur'an\", to je bilo u skladu sa onim što je Allahov Poslanik ﷺ ostavio kao oporuku. Abdullah ibn Ahmed ibn Hanbel prenosi svojim senedom od Talhe ibn Musrifa, koji je pitao Abdullaha ibn Ebu Evfaa: „Da li je Allahov Poslanik ﷺ ostavio oporuku?\" Rekao je: „Ne.\" Talha je rekao: „Zašto je onda muslimanima","propisano da ostavljaju oporuku?\" Rekao je: „Ostavio je Allahovu Knjigu kao svoju oporuku.\" Izvor: Kitabus sunna, Abdullah ibn Ahmed, tom 2, str. 537. Imam Abdullah ibn Ahmed preneo je ovaj hadis sa dva različita seneda, i oba su verodostojna. Zatim Abdullah ibn Ahmed prenosi svojim senedom od Ebu Džuhajfe, koji je rekao Aliji, radijallahu anhu: „Da li imaš nešto od Allahovog Poslanika ﷺ osim Allahove Knjige?\" Alija je rekao: „Tako mi Onoga koji je rascepio zrno i stvorio živo biće, mi nemamo ništa osim Allahove Knjige, osim što Allah čoveku podari razumevanje Kur'ana i onoga što je u ovom svitku.\" Ebu Džuhajfa je rekao: „A šta je u tom svitku?\" Rekao je: „Pamet, oslobađanje zarobljenika, i to da se musliman","ne ubija za ubistvo nevernika.\" Izvor: Kitabus sunna, Abdullah ibn Ahmed, tom 2, str. 538 539. Prema ovim verodostojnim predajama od Alije ibn Ebu Taliba i Abdullaha ibn Ebu Evfaa, Allahov Poslanik ﷺ nije ostavio nikakvu oporuku osim oporuke u vezi sa Kur'anom. Omer, dakle, nije pogrešio kada je rekao: „Dovoljan nam je Kur'an.\" Peto Poslanikove reči da izađu iz kuće Ostaje još tvrdnja da je Poslanik ﷺ ashabe isterao iz svoje kuće i da to ukazuje na to da su ga oni tokom bolesti vređali. Tusi svojim senedom prenosi od Zurare ibn A'jena, koji je rekao: Sedeo sam kod Ebu Džafera, mir neka je na njega, i s njim nije bilo nikoga osim njegovog sina Džafera, mir neka je","na njega. Rekao je: O Zurare, Ebu Zerr, radijallahu anhu, i Osman su se sporili za života Allahovog Poslanika ﷺ. Osman je rekao: U svakom imetku, bilo zlatu ili srebru, koji se obrće, koristi i njime se trguje, ima zekata nakon što na njemu prođe godina. Ebu Zerr, radijallahu anhu, rekao je: U onome što se koristi za trgovinu, ili se obrće, ili se troši, nema zekata. Zekat je u onome što je zakopano ili pohranjeno, pa ako na tome prođe godina, u tome ima zekata. Spor su izneli pred Allahovog Poslanika ﷺ, a on je rekao: Ispravan govor je govor Ebu Zerra. Tada je Ebu Abdullah, mir neka je na njega, rekao svome ocu: Kada već ne želiš da","se tako nešto izdvaja, kako onda ljudi treba da daju svojim siromasima i potrebnima? Njegov otac, mir neka je na njega, rekao je: Skloni se od mene, nemam drugog izlaza. Izvor: Tehzibul ahkam, Tusi, tom 4, str. 91 92. Obojica Medžlisija ocenili su ovu predaju verodostojnom, u Revdatul mutekin, tom 3, str. 44, i u Meladul ahjar, tom 6, str. 188. Na kraju hadisa Muhammed ibn Alija kaže svome sinu Džaferu: „Skloni se od mene\", na isti onaj način na koji je Poslanik ﷺ rekao ashabima: „Izađite, sklonite se od mene.\" Šta god, dakle, govorili o ashabima, isto to moraju reći i o Džaferu es Sadiku. Šesto Kur'an je bio Poslanikova oporuka Kur'an je čudo od Allaha i, prema verodostojnim","hadisima, bio je oporuka Njegovog Poslanika ﷺ. Ako je Poslanik ﷺ već bio ostavio oporuku u vezi sa Alijom, u smislu njegovog nasleđivanja i hilafeta, zašto bi onda Abbas govorio Aliji da ode i pita Poslanika ﷺ o tom pitanju? I zašto bi Alija rekao: „Tako mi Allaha, ako to zatražimo od Allahovog Poslanika, pa nam uskrati, ljudi nam to nakon toga nikada neće dati\"?"]},{"slug":"Fedek","chunks":["Ebu Bekr, radijallahu anhu, samo je postupio po naredbi Poslanika ﷺ, koji je rekao da poslanici ne ostavljaju nasledstvo. Predajom prihvatljivog seneda utvrđeno je da je Ebu Bekr zatražio dozvolu da uđe kod Fatime, da je sa njom razgovarao i da je ona preselila zadovoljna njime. Tu predaju ocenili su Zehebi, Ibn Kesir, Bejheki i Ibn Hadžer. Uz to, u predaji verodostojnog seneda Fatima Ebu Bekra oslovljava kao namesnika Allahovog Poslanika ﷺ. Šije godinama pokušavaju da protiv Ebu Bekra, radijallahu anhu, iskoriste događaj sa Fedekom. Kažu da je Ebu Bekr, radijallahu anhu, rasrdio Fatimu, a da prema sunijskoj literaturi srdnja Fatime znači i srdnju Poslanika ﷺ. Taj jeftin argument lako se pobija sledećim tačkama. Prvo Ebu Bekr je samo postupio","po naredbi Poslanika ﷺ Ako se Fatima naljutila na Ebu Bekra, radijallahu anhu, samo zato što se pokorio naredbi Poslanika ﷺ, koji je izjavio da poslanici ne ostavljaju nasledstvo, onda to nije Ebu Bekrova krivica. Mi ne verujemo da je Fatima bila nepogrešiva, što znači da je i ona bila podložna greškama, jednako kao što je i Ebu Bekr bio podložan greškama. Srdnja Fatime uznemirava ili vređa Poslanika ﷺ jedino onda kada je ona na ispravnoj strani, a onaj ko ju je rasrdio na pogrešnoj. Taj argument koji šije koriste, dakle, potpuno je neosnovan, jer se Ebu Bekr, radijallahu anhu, samo pokorio naredbi Poslanika ﷺ. Drugo i drugi su rasrdili Fatimu Ako su šije toliko sigurne u to da Ebu","Bekra, radijallahu anhu, treba odbaciti zato što je „rasrdio\" Fatimu, hoće li imati hrabrosti da odbace i Aliju ibn Ebu Taliba, koji je takođe rasrdio Fatimu, kako se navodi u predaji verodostojnog seneda u delu Ajnul hajat od Medžlisija, tom 2, str. 310? Prema toj predaji, Aliji je bila data jedna služavka. Kada je Fatima ušla u kuću, zatekla je Aliju kako leži u njenom krilu. Naljutila se na njega i otišla poslaniku Muhammedu ﷺ da se požali na ono što je videla. I hoće li šije imati istu hrabrost da odbace svog uglednog učenjaka poznatog kao Allame el Hilli, koji je rasrdio mehdija, kako navodi el Esterabadi u svom delu El Fevaidul medenijje, str. 91? Treće Fatima je preselila","zadovoljna Ebu Bekrom Predajom dobrog i prihvatljivog seneda utvrđeno je da je Ebu Bekr, radijallahu anhu, zatražio dozvolu da uđe u Fatiminu kuću. Nakon što mu je Alija dozvolio da uđe, razgovarao je sa Fatimom i zadovoljio je, tako da je ona napustila ovaj svet zadovoljna njime. Ta predaja nalazi se u delu Sijeru a'lamin nubela, Zehebi, tom 2, str. 121. Imam Ibn Kesir takođe spominje ovaj hadis i komentariše ga rečima: „Ovo je dobar i jak sened.\" Izvor: El Bidaje ven nihaje, Ibn Kesir, tom 5, str. 289. Imam Bejheki takođe spominje predaju i ocenjuje je rečima: „Ovo je dobar mursel sa verodostojnim senedom.\" Izvor: Es Sunenul kubra, Bejheki, tom 6, str. 491. Imam Ibn Hadžer el Askalani o","ovom hadisu je rekao: „Iako je mursel, njegov sened do Ša'bija je verodostojan.\" Izvor: Fethul bari, Ibn Hadžer el Askalani, tom 6, str. 202. Četvrto odgovor na primedbu o prekinutom senedu Šije tvrde da je sened ove predaje prekinut između Alije, radijallahu anhu, i Ša'bija, i da je hadis zbog toga nepouzdan i slab. Na to kažemo da se pojedini mursel hadisi prihvataju, zavisno od prenosioca. U ovom slučaju, mursel predaje Ša'bija prihvatljive su prema mišljenju pojedinih hadiskih učenjaka. Imam Zehebi je rekao: Poput mursel predaja Mudžahida, Ibrahima i Ša'bija. To je dobar mursel u kojem nema smetnje. Jedni ga prihvataju, a drugi odbacuju. Izvor: El Mukiza, Zehebi, str. 40. Imam Idžli je rekao: „Ša'bijev mursel je verodostojan. On gotovo","da ne prenosi mursel osim verodostojnog.\" Izvor: Ma'rifetus sikat, Idžli, tom 2, str. 12; Tezkiretul huffaz, Zehebi, tom 1, str. 79. Dr Džemal ibn Muhammed es Sejjid u svom delu Ibnul Kajjim ve hidmetuhu, tom 1, str. 414, kaže: Najviše što se o Ša'bijevim mursel predajama može reći jeste da je o njima postojalo razilaženje. Iako iz očiglednog govora imama proizlazi da ih prihvataju, nisam naišao na ime nekoga ko je presudio da se odbacuju, kako je to smatrao Ibnul Kajjim. Iako je Zehebi ukazao na skupinu koja je rekla da se odbacuju, one su bliže prihvatanju nego odbacivanju, a Allah najbolje zna. Peto nema verodostojne predaje o njenoj srdnji Ne postoji nijedna jasna verodostojna predaja u kojoj Fatima kaže","da je ljuta na Ebu Bekra i Omera, radijallahu anhuma. Hadis u kojem se navodi da su Alija, radijallahu anhu, i drugi svedočili u njenu korist neistinit je, kako navodi Hammad ibn Ishak ibn Ismail u svom delu Terikatun nebijj, str. 86. U hadisu verodostojnog seneda Fatima, radijallahu anha, oslovljava Ebu Bekra, radijallahu anhu, rečima „namesniče Allahovog Poslanika ﷺ\", što znači da ga je priznala kao halifu. A kada joj je saopštio da ne može naslediti Fedek, odgovorila je: „Ti i Allahov Poslanik najbolje znate.\" Izvor: Musned Ebu Ja'la, tom 12, str. 119. Zaključak 1. Ebu Bekr, radijallahu anhu, nije učinio nepravdu Fatimi u pitanju Fedeka. 2. Fatima je preselila zadovoljna Ebu Bekrom."]},{"slug":"Hadis-o-skripanju-Arsa","chunks":["Svih šest predaja o škripanju Arša slabe su, izmešane ili izmišljene, što su utvrdili Albani, Ibn el Dževzi, Bejheki, Zehebi i Ibn Usejmin. Izraz „škripi poput sedla\" potiče od samih prenosilaca, Vehba, Ibn el Ezhera i Jahjaa ibn Meina, a ne od Poslanika ﷺ. Predaje protivreče jedna drugoj, protivreče verodostojnoj islamskoj akidi i protivreče zdravom razumu. Sam Zehebi kaže da škripanje uopšte nije Allahovo svojstvo. Rafidije navode određene predaje u kojima se tvrdi da Allah sedi na Aršu i da se iz njega čuje škripanje poput škripanja sedla, i time se rugaju islamskom verovanju. Sve takve predaje su slabe i nijedna nije verodostojna, ni sa lancem koji seže do Poslanika ﷺ ni do ashaba. Prvo analiza šest predaja, lanac po","lanac Prva predaja pripisana Omeru ibn el Hattabu Pričao nam je Abdur Rahman, od Sufjana, od Ebu Ishaka, od Abdullaha ibn Halife, od Omera, da je rekao: Kada Blagoslovljeni i Uzvišeni sedne na Arš, iz Njega se čuje škripanje poput škripanja novog sedla. Ocena: slaba i mursel. Dve su kobne mane. Prva, prenosilac Abdullah ibn Halifa jeste kufanski tabiin koji nikada nije sreo Omera ibn el Hattaba niti je od njega išta čuo, čime je lanac prekinut. Druga, on je nepoznat prenosilac čija pouzdanost nije utvrđena. Ibn Kesir u El Bidaje ven nihaje, 1/18, kaže: „Abdullah ibn Halifa nije toliko poznat, a postoji sumnja u to da je čuo od Omera.\" Drugi prenosilac, Ebu Ishak es Sebii, poznat je po","tedlisu, odnosno po prikrivanju predaja koje je uzeo od nepoznatih ljudi. Njegov hadis se ne prihvata osim ako izričito navede da je neposredno čuo, jer pripada trećoj skupini onih koji čine tedlis. Ta predaja, uz to, uopšte nije od Poslanika ﷺ, nego je lažno pripisana samom ashabu Omeru ibn el Hattabu. Druga predaja pripisana neposredno Poslaniku ﷺ Pričao nam je Abdullah ibn Redža, obavestio nas je Israil, od Ebu Ishaka, od Abdullaha ibn Halife, koji je rekao: Došla je žena Poslaniku ﷺ i rekla: Moli Boga da me uvede u Džennet. Poslanik ﷺ je veličao Gospodara i rekao: Njegov Arš se prostire nad nebesima i Zemljom, i On sedi na njemu, i od njega ne ostaje ništa osim širine četiri","prsta, i on škripi poput škripanja novog sedla kada ga neko uzjaše, pa mu bude pretežak. Ocena: slaba, izmešana, i protivreči prvoj predaji. Abdullah ibn Halifa ovde prenosi neposredno od Poslanika ﷺ, iako ga nikada nije sreo, nije od njega čuo, niti je živeo u njegovo vreme. Lanac je, dakle, prekinut. Uz to, predaja izravno protivreči prvoj predaji u pogledu pripisivanja: jednom Omeru, a jednom neposredno Poslaniku ﷺ. Ta pometnja i sama je dokaz nepouzdanosti. Treća predaja pripisana Ebu Musau el Eš'ariju Od Ibn Džuhade, od Seleme ibn Kuhejla, od Amare ibn Umejra, od Ebu Musaa, koji je rekao: Kursija je mesto na kojem počivaju stopala, i ona škripi poput škripanja sedla. Ocena: slaba, u lancu postoji praznina. Šejh Ahmed","Šakir, u komentaru Taberijevog tefsira, 5/398, kaže: „Hadis je prekinut, jer Amara ibn Umejr nije sreo Ebu Musaa el Eš'arija.\" Četvrta predaja od samog Ša'bija Pričao nam je Ibrahim, pričao nam je Ubejd ibn Adem el Askalani, pričao nam je moj otac, od Hammada ibn Seleme, od Ataa ibn es Saiba, od Ša'bija, koji je rekao: Allah, Blagoslovljeni i Uzvišeni, je na Aršu, do te mere da on škripi poput škripanja sedla. Ocena: slaba glasina, nije pripisana ni Poslaniku ﷺ ni ijednom ashabu. Ovo je od samog Ša'bija, slaba predaja koja je u njegovo vreme bila raširena poput glasine, pa ju je i on ponovio. Ibn Usejmin, u komentaru Safarinijeve akide, str. 297, kaže: „Ovaj hadis je upitan.\" Peta predaja","izmišljena, pripisana Poslaniku ﷺ Pričao nam je Ubejd ibn Jaiš, pričao nam je Ebu Jezid el Muanna, pričao nam je Israil, od Džafera ibn ez Zubejra, od El Kasima, od Ebu Umame, koji je rekao: Allahov Poslanik ﷺ je rekao: Molite Allaha za Firdevs, jer je on tajna Dženneta, a stanovnici Firdevsa čuju škripanje Arša. Ocena: izmišljena. Predaja prolazi kroz Džafera ibn ez Zubejra, poznatog lažljivca i izmišljača hadisa. Imam Hejsemi je taj hadis izostavio iz Medžmeuz zevaida, čime je ukazao da je Džafer ibn ez Zubejr odbačen prenosilac. Albani ga je takođe oslabio. Šesta predaja umetnuta, škripanje potiče od prenosilaca Muhammed ibn Ishak, prenoseći od Jakuba ibn Utbe, od Džubejra ibn Muhammeda ibn Džubejra ibn Mut'ima, od njegovog oca,","od njegovog dede Džubejra ibn Mut'ima: Allahov Poslanik ﷺ rekao je beduinu u hadisu o traženju kiše: Teško tebi! Znaš li ko je Allah? Njegov položaj je previše uzvišen da bi se kod Njega neko posredovao. On je iznad Svog Arša, iznad Svojih nebesa. Ocena: slaba. A izraz „škripanje\" uopšte nije od Poslanika ﷺ, nego je umetak samih prenosilaca. Muhammed ibn Ishak jeste prenosilac koji čini tedlis i nije izričito naveo da je to neposredno čuo. Albani ga je oslabio, Šuajb el Arnaut oslabio ga je u komentaru Tahavijeve akide, a Vadii u delu Eš Šefaa, str. 191. Bejheki, u El Esma ves sifat, 2/159, kaže: To prenosi jedino Muhammed ibn Ishak, a ako se on ne uzima kao oslonac","u pitanjima dozvoljenog i zabranjenog, onda to tim pre važi za Allahova svojstva. Kritikovali su ga jedino zbog prenošenja od sledbenika Knjige i od slabih prenosilaca, i zbog prikrivanja njihovih imena. U ovom hadisu nije jasno naveo da je čuo od Jakuba i Džubejra, a postoji i razilaženje o samoj formulaciji. Albani, u komentaru Miškatul mesabiha, br. 5660, kaže: „Njegov sened je slab, i ne postoji nijedan verodostojan hadis o škripanju Arša.\" Izraz „škripanje\" potiče od reči samih prenosilaca, Vehba, Ibn el Ezhera i Jahjaa ibn Meina, a ne od Poslanika ﷺ. Izvori to izričito beleže: 1. El Arš ve ma ruvije fihi: „Vehb je to opisao, nagnuo svoju desnu ruku i prste, i rekao: I škripi s njim kao","što sedlo škripi sa jahačem.\" 2. Šerhus sunne: „Vehb je pokazao rukom poput kupole, a i Ebul Ezher je pokazao i rekao: I škripi s njim kao što sedlo škripi sa jahačem.\" 3. Ibn Abdul Berr, Et Temhid: „Jahja ibn Mein je pokazao svojim prstima u obliku kupole, i škripalo je kao što sedlo škripi sa jahačem.\" 4. Zehebi, El Uluvv: „I Ibn el Ezher je takođe ukazao: I škripi s njim kao što sedlo škripi sa jahačem.\" 5. Ibn Hajsema, Et Tarihul kebir: „Jahja ibn Mein je pokazao svojih pet prstiju u obliku kupole, i škripalo je kao što sedlo škripi sa jahačem.\" Sam Zehebi je prokomentarisao: „Ovo je veoma čudan i usamljen hadis. Ibn Ishak je autoritet za","vojne pohode kada navede sened. Ima čudne predaje, a Allah najbolje zna da li je Poslanik ﷺ to rekao ili nije. Tako mi Allaha, ništa Njemu nije slično.\" Reč je, dakle, o umetnutom hadisu, u kojem su lične reči prenosioca pomešane sa rečima Poslanika ﷺ. Ta greška se otkriva upoređivanjem lanaca međusobno. Predaje koje izraz „škripanje\" izričito pripisuju samom Poslaniku ﷺ preneo je slabi prenosilac Ebu Hamid Ahmed ibn Ali ibn Hasanuvejh, a Hatib el Bagdadi ih nije ocenio verodostojnim. Protivrečnosti između predaja Imam Ibn el Dževzi, u El Ilelul mutenahije, kaže: Ovo je hadis koji nije verodostojan od Allahovog Poslanika ﷺ, a njegov sened je veoma izmešan. Ponekad ga Ibn Halifa prenosi od Omera, od Allahovog Poslanika ﷺ. Ponekad","ga zaustavi kod Omera, a ponekad kod samog Ibn Halife. Ponekad stoji „od njega ne ostane ništa osim koliko četiri prsta\", a ponekad drugačije. Sve je to pometnja prenosilaca, pa se na to ne može osloniti. Protivrečnosti kroz svih šest predaja očigledne su: ponekad je škripanje Kursije, ponekad Arša; ponekad Abdullah ibn Halifa to pripisuje Poslaniku ﷺ, ponekad Omeru, ponekad sebi samom; formulacija o „četiri prsta\" menja se iz verzije u verziju. Ništa od toga nije u skladu sa verodostojno prenesenim tekstom. Drugo odgovor onima koji tvrde da je predaja verodostojna Pozivanje na Zehebija Sam Zehebi oslabio je Abdullaha ibn Halifu kao nepoznatog, rekavši u El Mizanu, 2/414, da je „jedva poznat\", a u El Aršu, 2/153: „Ne znamo za","njegov položaj u pogledu kritike ili pohvale.\" Najodlučnije je, međutim, ono što je sam Zehebi naveo u El Uluvvu, str. 39: Škripanje uopšte nema mesta među svojstvima. Naprotiv, to je poput podrhtavanja Arša prilikom smrti Sa'da, ili raspuknuća neba na Sudnjem danu, i slično tome. Sačuvaj Bože da to smatramo Allahovim svojstvom. Uz to, reč škripanje ne dolazi iz verodostojnog teksta. Pozivanje na Ibn Hibbana Ibn Hibban je bio poznat po krajnjoj popustljivosti u ocenjivanju prenosilaca pouzdanim, do te mere da učenjaci hadiske kritike ne prihvataju njegovu ocenu prenosioca ako je on jedini koji ga je ocenio pouzdanim. Pozivanje na Ebu Muhammeda ed Daštija Njegova tvrdnja da „njegovi prenosioci ispunjavaju uslove Buharije i Muslima\" dobila je Albanijev odgovor: „To je","jasna, dvostruka greška. Hadis nije verodostojan, a njegovi prenosioci ne ispunjavaju njihove uslove. Po mom mišljenju, to je odbačen hadis.\" Pozivanje na Ibnul Kajjima Ibnul Kajjim je pokušao da predaju ojača preko Abdullaha ibn el Hakema el Katvanija i Osmana ibn Ebu Šejbe, ali nije uočio da su predaje slabe iz sasvim drugih razloga. Pozivanje na Hejsemija Njegova tvrdnja da su prenosioci iz ljudi Sahiha jeste njegova greška. Nijedan od autora četiri Sunena ni dva Sahiha nije prenosio od Abdullaha ibn Halife. Pozivanje na ćutanje A'meša i Sufjana Obojica su pogrešno poverovali u sadržaj ovog hadisa, jer njegov sened nije verodostojan. Sufjan ga je preneo preko Ebu Ishaka, ali to ne utvrđuje njegovu verodostojnost, nego samo to da su neki","previdели njegovu slabost. Treće predaje protivreče akidi i zdravom razumu 1. Slabi hadis kaže da Allah „sedi na Kursiji\", a Kur'an i verodostojni sunnet utvrđuju da je Allah iznad Arša, a ne na Kursiji. To su dve različite stvari. Pojedini su bili primorani da reč „kursija\" iskrive i protumače kao „Arš\" da bi izbegli tu protivrečnost. 2. Hadis tvrdi da nakon što Allah sedne, od Kursije ostaje nepokriveno samo četiri prsta širine. To nijedan zdrav razum ne prihvata, jer bi značilo da je Arš veći od Allaha za četiri prsta, što je i nerazumno i sa stanovišta verovanja nedopustivo. 3. Hadis tvrdi da stanovnici Dženneta čuju škripanje Arša. Ogromno škripanje bilo bi glasna i uznemirujuća buka, što izravno protivreči spokoju","i miru Dženneta koje Kur'an izričito opisuje. Zaključak Svih šest predaja o škripanju Arša slabe su, umetnute ili izmišljene, što su utvrdili Albani, Ibn el Dževzi, Bejheki, Zehebi i Ibn Usejmin. Izraz „Arš škripi poput sedla\" potiče od samih prenosilaca, Vehba, Ibn el Ezhera i Jahjaa ibn Meina, a ne od Poslanika ﷺ. Predaje protivreče jedna drugoj, protivreče verodostojnoj islamskoj akidi i protivreče zdravom razumu. Nema, dakle, ničega što bi se moglo upotrebiti protiv islamskog verovanja."]},{"slug":"Izmisljena-predaja-o-Fatimi","chunks":["Predaja nema verodostojan sened i mursel je. Imam Zehebi označio ju je kao izmišljenu u Mizanul i'tidalu, 4/460. Hafiz Ibn Hadžer u Lisanul mizanu, 6/228, ukazao je da joj protivreči sama hronologija, jer je Fatima rođena znatno pre Israa, kada je namaz postao obavezan, a istorijski zapisi potvrđuju da je Hatidža preselila pre toga. Hatib el Bagdadi je u Tarihu Bagdada, 5/292 293, uz sened naveo da je Muhammed ibn el Halil nepoznat. Izjava o kojoj je reč potiče iz šijskih izvora, nema verodostojan sened i spada u mursel predaje. Ocene učenjaka Imam Zehebi označio ju je kao izmišljenu. Izvor: Mizanul i'tidal, 4/460. Hafiz Ibn Hadžer u Lisanul mizanu, 6/228, primetio je da je onaj ko je izmislio ovu predaju","bio nepažljiv, jer je Fatima rođena znatno pre Israa, kada je namaz postao obavezan, a istorijski zapisi potvrđuju da je Hatidža preselila pre toga. Hatib el Bagdadi uvrstio je ovaj hadis u Tarih Bagdada, 5/292 293, sa njegovim senedom, ali je naveo da je „Muhammed ibn el Halil nepoznat\", što ukazuje na slabost. Navođenje hadisa uz njegov izvor razjašnjava odgovornost za predaju. Savremeni pristup, međutim, iziskuje da učenjaci izričito navedu stepen verodostojnosti hadisa, a ne da samo navedu sened, kako su to činili raniji učenjaci."]},{"slug":"Korisni-sajtovi-za-odgovore-na-sijske-tvrdnje","chunks":["Ovo je spisak izvora, a ne rasprava. Navedeni sajtovi bave se odgovorima na šijske tvrdnje, odbranom ashaba i porodice Poslanika ﷺ, kao i objavljivanjem skenova iz šijskih knjiga. Sadržaj je na engleskom, arapskom i urdu jeziku. Reč je o spoljnim sajtovima koji nisu pod našom uredničkom kontrolom. Preporučuje se da se navodi sa njih uvek provere u izvornim delima. You Punctured The Ark U odbranu porodice Poslanika ﷺ i ashaba. You Punctured The Ark O Rafidah In Defense of the Aal and Ashaab Sa istog sajta, opsežan odgovor u vezi sa Fedekom i nasledstvom poslanikâ, kao pobijanje poznatog šijskog sajta Shiapen.com, ranije poznatog kao Answering Ansar.org: Sunni Answers to Shiapen's article on Fadak and inheritance of the Prophet ﷺ Gift","2 Shias Gift2Shias Shia Scans Objavljivanje skenova iz šijskih izvora. Autor je Hasan eš Šimrani. Shia Scans Zvanični sajt istraživača Ramija Ise Zvanični sajt istraživača Ramija Ise TwelverShia.net Cilj ekipe sajta TwelverShia.net jeste da ponudi verodostojnu alternativu prikazu islamske istorije koji se putem raznih šijskih sajtova širi na internetu. TwelverShia.net Refuting Shia Allegations Online Everywhere Shia Neem Rafzi Expose Sadržaj na urdu jeziku, o vrednosti Ebu Bekra es Siddika, radijallahu anhu, u svetlu verodostojnih hadisa i verovanja ashaba. Shia Neem Rafzi Expose"]},{"slug":"Mit-o-dojenju-odrasle-osobe","chunks":["Većina učenjaka i imami četiri mezheba slažu se da dojenje deteta starijeg od dve godine ne uspostavlja zabranu braka. Aišino izdvojeno mišljenje ticalo se deteta starijeg od dve godine, a ne odraslog čoveka, kako to šire oni koji lažu. Sama Aiša prenosi hadis „Dojenje je samo od gladi\". Slučaj Salima bio je poseban propis vezan za njega, a i tada je pio iz odvojene posude, ne dodirujući Sehlu niti je videvši. Ovo je pojednostavljena verzija opširnijih rasprava o istoj temi. Prvo stav većine učenjaka Većina učenjaka i imami četiri mezheba slažu se da dojenje deteta koje je prešlo dve godine života ne utiče na zabranu braka sa tom ženom. Drugo na šta se odnosilo Aišino izdvojeno mišljenje Što se tiče","odstupanja majke vernika Aiše od te saglasnosti, ono se odnosilo na dojenje deteta koje je prešlo dve godine života, a ne na odraslog čoveka, kako to šire oni koji lažu. Sama Aiša prenosi od Poslanika ﷺ hadis: „Dojenje je samo od gladi\", što znači ono što dete zasiti i zadovolji njegovu potrebu. Nije, dakle, razumno da bi ona to prenela, a zatim izdala fetvu kojom dozvoljava dojenje odraslog čoveka. Treće razgovor Umm Seleme i Aiše Na to ukazuje i ono što Muslim prenosi iz razgovora između Umm Seleme i Aiše, iz kojeg je jasno da se spor ticao isključivo dojenja odojčadi nakon navršene dve godine, a ne dojenja odraslih. Četvrto predaja o Sehli bint Suhejl Što se tiče predaje o","Sehli bint Suhejl, ona se odnosi na poseban propis vezan za Salima, kojeg je ona odgajala u svom domu još od njegovog detinjstva, a radi otklanjanja nelagode zbog njegovog ulaska kod nje nakon što je dostigao punoletstvo. Majke vernika, ashabi i većina učenjaka jednoglasno su se složili da je to bio propis poseban za Salima, koji je u tom trenutku prestao da važi i koji se ne može razumeti niti primeniti kao opšte pravilo. Peto kako je Salim zapravo dojen U Salimovom dojenju nije bilo ničega od onoga što se javlja u bolesnim maštanjima hrišćana, ateista i onih koji idu njihovim stopama među posvetovnjačenim muslimanima. Naprotiv, njegovo dojenje bilo je iz odvojene posude iz koje je pio, a da nije","dodirivao Sehlu, pa čak ni da ju je video. Nije ni razumno da bi mu bilo zabranjeno da vidi njenu kosu i njene ruke i noge, i da se zbog toga uopšte postavlja pitanje, a da mu istovremeno bude dozvoljeno da vidi njena prsa ili da je dodirne. Šesto izdvojene izjave savremenih učenjaka Ne uzimaju se u obzir izdvojene izjave koje se prenose od pojedinih poznijih učenjaka u savremeno doba, naročito kada se zna da su ih povukli i da ih više ne zastupaju."]},{"slug":"Namesnik-svakom-verniku-nakon-mene","chunks":["Verodostojnost seneda ne povlači za sobom verodostojnost teksta, što navode Ibn Kesir, Sujuti i Ibn Salah. Sam Albani, iako je sened ocenio dobrim, sadržaj ove predaje izričito je odbacio. U senedu se nalazi Ebu Beldž, o kojem Ibn Hibban kaže da mu se ne uzimaju one predaje koje prenosi sam, a upravo je ova predaja od onih koje je preneo jedino on. Ahmed ibn Hanbel nazvao ju je munker predajom, a Ibn Tejmijje i Zehebi laži pripisanom Poslaniku ﷺ. Imam Ibn Ebu Asim prenosi svojim senedom od Ibn Abbasa, radijallahu anhu, da je Poslanik ﷺ rekao Aliji ibn Ebu Talibu, radijallahu anhu: „Ti si meni kao što je Harun bio Musau, s tim što ti nisi poslanik, i ti si","moj namesnik svakom verniku nakon mene.\" Treba imati na umu da je ovaj hadis, koji spominje imam Ibn Ebu Asim, izvorno deo duže predaje sa istim senedom, o vrednostima Alije ibn Ebu Taliba. Ebu Beldž je prenosi od Amra ibn Mejmuna, a on od Ibn Abbasa. Ovo objašnjenje obradiće sledeće tačke: 1. Albanijev stav o verodostojnosti ove predaje. 2. Da li je Ebu Beldž pouzdan? 3. Izjave učenjaka o ovom hadisu. Prvo ocena seneda ne jamči ispravnost teksta Albanijeva ocena da je sened dobar ne jamči nužno pouzdanost samog teksta. To zna svako ko je proučavao pravila hadiske nauke. Imam Ibn Kesir, Allah mu se smilovao, rekao je: Ocena da je sened verodostojan ili dobar ne povlači za sobom istu","ocenu za tekst hadisa, jer on može biti neuobičajen ili sadržati skrivenu manu. Imam Sujuti je rekao: Verodostojnost seneda ne povlači za sobom verodostojnost teksta, kao što je utvrđeno u hadiskim naukama, jer je moguće da sened bude verodostojan, a da tekst sadrži neuobičajenost ili manu koja sprečava njegovu verodostojnost. Ibn Salah je rekao: Njihove reči „ovaj hadis je verodostojan ili dobar po svom senedu\" razlikuju se od njihovih reči „ovaj hadis je verodostojan ili dobar\", jer se može reći „ovaj sened hadisa je verodostojan\", a da tekst ne bude verodostojan zbog neuobičajenosti ili mane. Dr Mahmud et Tahan je rekao: „Moguće je da sened bude verodostojan ili dobar, a da tekst to ne bude, zbog neuobičajenosti ili mane.\" Uz","to, sam Albani se osvrnuo na ovu predaju rekavši: A što se tiče onoga što šije spominju u vezi sa ovim hadisom i drugima, poput hadisa o položaju, da je Poslanik ﷺ o Aliji, radijallahu anhu, rekao „On je moj namesnik nakon mene\", to nije ispravno ni na koji način. Naprotiv, to je jedna od njihovih brojnih neistina za koje je istorija dokazala da su laži. Jer, kada bismo zamislili da je Poslanik ﷺ to rekao, onda bi se to i dogodilo onako kako je rekao, budući da je to objava, a Uzvišeni Allah ne krši Svoje obećanje. Jasno je, dakle, da Albani ne prihvata sadržaj ovog hadisa, iako je sened ocenio dobrim. Drugo da li je Ebu Beldž pouzdan?","U senedu ovog hadisa nalazi se prenosilac po imenu Ebu Beldž, punim imenom Jahja ibn Selim ibn Beldž. Za tog prenosioca se, iako je bio iskren, navodi da je pravio mnogo grešaka u prenošenju hadisa, pa se od njega prihvataju samo one predaje koje su potkrepljene drugim putevima. Imam Ibn Hibban, Allah mu se smilovao, o njemu je rekao: Prenosi od Amra ibn Mejmuna. Bio je od onih koji su grešili. Njegove greške, međutim, nisu bile toliko teške da bi zaslužio da bude odbačen, niti je učinio nešto što običan čovek ne bi učinio, pa prema njemu treba biti pravedan. Zato smatram da se treba suzdržati jedino od onih predaja koje prenosi sam. Šejh Šuajb el Arnaut, Allah mu se","smilovao, o ovoj predaji je rekao: Slaba je u ovom kontekstu. Najpravednije što je o njemu rečeno jeste da se njegov hadis prihvata sve dok nije jedini koji ga prenosi, kako je rekao Ibn Hibban u El Medžruhinu. A upravo je ova predaja, sa formulacijom „Ne priliči mi da napustim ovaj svet, a da on ne bude moj namesnik nad svakim vernikom nakon mene\", od onih koje je Ebu Beldž preneo sam. Zato se ne prihvata. Treće mišljenja učenjaka o ovom hadisu Učenjaci koji su ga smatrali verodostojnim Jedan od učenjaka koji su ovu predaju ocenili verodostojnom jeste imam Hakim en Nejsaburi, u svom poznatom delu El Mustedrek. Poznato je, međutim, da je Hakim popustljiv kada je reč o ocenjivanju","slabih predaja verodostojnim. Drugi učenjak kojeg često navode jeste šejh Ahmed Šakir. Ni to, međutim, nije dovoljno, jer on kaže da je sened verodostojan, a već je pokazano da verodostojnost seneda ne jamči verodostojnost sadržaja predaje. Učenjaci koji su hadis odbacili Učenjaka koji su ovaj hadis odbacili mnogo je više i mnogo su verodostojniji od onih koji su ovu slabu predaju ocenili verodostojnom. 1. Imam Ahmed ibn Hanbel, Allah mu se smilovao, rekao je za Ebu Beldža: „Preneo je munker hadis.\" 2. Imam Ibn Redžeb el Hanbeli, Allah mu se smilovao, naveo je da je munker hadis na koji je imam Ahmed mislio upravo ta duža predaja koju je Ebu Beldž preneo od Amra ibn Mejmuna, od Ibn Abbasa, o","vrednostima Alije, radijallahu anhuma. 3. Ibn Tejmijje, Allah mu se smilovao, naveo je da je taj hadis laž pripisana Poslaniku ﷺ. 4. Imam Zehebi, Allah mu se smilovao, potvrdio je izjavu Ibn Tejmijje. 5. Albani, kako je već spomenuto. 6. Šejh Šuajb el Arnaut, u fusnotama Musneda imama Ahmeda. Zaključak Predaje Ebu Beldža prihvataju se samo ako su došle i drugim putevima u kojima on nije uključen. A u slučaju hadisa o kojem je reč, Ebu Beldž je jedini koji ga prenosi u toj formulaciji. Uz to, pojedini učenjaci su zapisali da je Harun, mir neka je na njega, preselio pre Musaa, mir neka je na njega, pa ta predaja ni ne može značiti nasleđivanje u smislu namesništva nakon smrti."]},{"slug":"Odgovor-na-optuzbe-protiv-Velida-i-Muhammeda-ibn-Haruna","chunks":["Optužbe se zasnivaju na predajama koje su slabe ili uopšte nemaju sened. Predaju o Velidu prenosi Amr ibn Mervan el Kelbi, nepoznata ličnost, a izgovorio ju je Sulejman, koji je bio neprijateljski raspoložen prema Velidu, što spada u takozvanu kritiku među savremenicima. Predaju o Muhammedu ibn Harunu prenosi Vakidi, odnosno u drugoj verziji uopšte nema seneda, a ona protivreči poznatoj istoriji, jer je Muhammed ibn Harun imao ženu i sina. Sadržaj optužbe Jedan od neprijatelja islama tvrdi da su Omer ibn el Hattab, Velid ibn Jezid i Muhammed ibn Harun er Rešid bili homoseksualci. Prvo optužba protiv Omera ibn el Hattaba Ta tvrdnja je besmislena i istorijski netačna. Savremene šije prve su optužile Omera ibn el Hattaba za jednu odvratnu","stvar, tvrdeći pritom da se to spominje u sunijskim knjigama. Ono što šije tvrde, međutim, jeste laž. To se u sunijskim knjigama uopšte ne spominje, a nije se spominjalo ni u knjigama ranih šija. Prvi koji je tu laž izmislio bio je šija Nimetullah el Džezairi, koji je preselio pre otprilike tri veka. El Džezairi je tvrdio da je Sujuti u svom delu Hašijetul kamus naveo tu tvrdnju o Omeru ibn el Hattabu. Sujuti, međutim, uopšte nije napisao knjigu pod tim naslovom. Ta knjiga je izmišljena i plod je pukih obmana pomenutog šije koji je lagao. Uz to, nije ni razumno da bi poslanik Muhammed ﷺ prijateljevao i sedeo sa takvim čovekom, i da bi mu dao svoju kćerku Hafsu","za ženu. Drugo optužba protiv Velida ibn Jezida Što se tiče Velida ibn Jezida, nije verodostojno preneseno da je bio takav. Predaje koje neprijatelji islama protiv njega navode nisu verodostojne, a to su sledeće. Taberijeva predaja Taberi u svom delu Et Tarih, 7/250 251, prenosi: Od Ahmeda ibn Zuhejra, sina Ebu Hajseme, od Medainija Alije ibn Muhammeda, od Amra ibn Mervana el Kelbija: Kada je Velid ubijen, odsečena mu je leva ruka i poslata Jezidu ibn el Velidu… Zatim je naredio da se glava odnese njegovom bratu Sulejmanu, a Sulejman, Velidov brat, bio je među onima koji su tražili da se njegov brat ubije. Ibn Ferve je oprao glavu, stavio je u korpu i doneo Sulejmanu. Sulejman je pogledao i","rekao: Nosite ga! Svedočim da je bio pijanica i raskalašan čovek. Taj raskalašnik hteo je da me ubije. Ibn Ferve je izašao iz kuće i srela ga je Velidova robinja. Rekao joj je: Teško tebi, kako li me je žestoko prokleo! Tvrdio je da je hteo da ga ubije. Rekla je: Tako mi Allaha, lagao je opaki. Nije to učinio. Ta predaja je slaba, jer je prenosilac Amr ibn Mervan el Kelbi, ili Omer ibn Mervan el Kelbi, nepoznata ličnost o kojoj nije potvrđena nikakva ocena. Zatim, u samoj priči stoji da je Velidova robinja branila Velida nakon njegove smrti i potvrdila da nije bio takav. Iz reči Ibn Ferve razume se i to da on nije poverovao Sulejmanovim rečima","kada je rekao da je Velid bio raskalašan. Uz to, Sulejman je bio neprijateljski raspoložen prema Velidu, pa tu izjavu od njega ne možemo prihvatiti, jer se to naziva kritikom među savremenicima. Predaja Ibn Sa'da Ibn Sa'd u delu Et Tabekatul kubra, 5/355 356, spominje: Obavestio nas je Muhammed ibn Omer. Rekao je: pričao nam je Abdur Rahman ibn Ebu Zinad, od svog oca, koji je rekao: Zuhri bi stalno kritikovao Hišama ibn Abdul Melika zbog smenjivanja Velida ibn Jezida… I rekao mu je: Nije ti dozvoljeno da učiniš ništa osim da ga smeniš. Ali Hišam to nije mogao učiniti zbog ugovora koji je s njim sklopio. Ta predaja je slaba, jer ju je preneo Vakidi, koji je lagao, a","on je pripisuje Abdur Rahmanu ibn Ebu Zinadu, koji je slab prenosilac. Zatim, ne znamo ni kako je Zuhri došao do tog podatka o Velidu, tim pre što su Zuhrijeve prekinute predaje veoma slabe. Uz to, u predaji se ni izričito ne spominje ono za šta se Velid optužuje. Treće optužba protiv Muhammeda ibn Haruna er Rešida Što se tiče Muhammeda ibn Haruna er Rešida, nije verodostojno da je činio ono za šta se optužuje. U Taberijevoj istoriji, 8/508, spominje se: Spomenuto je od Hamida ibn Seida, koji je rekao: Kada je Muhammed zavladao, i kada mu je Me'mun pisao i dao mu prisegu, tražio je evnuhe i kupovao ih, i za njih je plaćao visoku cenu, i učinio ih","svojom pratnjom noću i danju, i oni su bili ti koji su se brinuli o njegovoj hrani i piću, i o njegovim naredbama i zabranama, i odbio je slobodne žene i robinje. Ta predaja je slaba i neverodostojna, jer uopšte nema seneda, i ne znamo ko je tu glasinu pokrenuo. Uz to, u predaji se ne kaže ono što joj se pripisuje. Sve što se u njoj spominje jeste da ih je skupo kupovao i da su sa njim boravili u upravnim poslovima. To se može razumeti i tako da u upravnom veću nije sedeo sa ženama. Ta slaba predaja, uzgred, protivreči istoriji. Istorija nam govori da Muhammed ibn Harun nije odbijao žene i robinje, nego da je imao ženu","po imenu Lubana bint Ali el Mehdi, kao i sina po imenu Musa. Kada je preselila njegova robinja, majka njegovog sina, Muhammed ibn Harun bio je duboko ožalošćen njenom smrću. Muhammed ibn Harun imao je i više robinja koje su ga služile. Štaviše, Muhammed ibn Harun zatvorio je Ebu Nuvasa zbog razvrata, a zatim ga pustio i naredio mu da se kloni pijenja alkohola i takvih dela. To spominje Ibn Kesir u delu El Bidaje ven nihaje. Zaključak Suština je da su šije izvrtale sliku o emevijskim i abasijskim vladarima i izmišljale o njima laži, tim pre što su pojedine šije stale na stranu Me'muna protiv el Emina Muhammeda ibn Haruna. Što se tiče onih koji navode Zehebijeve reči, Zehebi","je kasniji istoričar i oslonio se na neke od tih ranijih slabih predaja, bez provere. Na njih je već odgovoreno, pa nema potrebe navoditi Zehebija. Islam nalaže dovođenje istinoljubivih svedoka koji će svedočiti protiv bilo kojeg grešnika, bio on pijanica, bludnik ili neko drugi. Pa gde su ti istinoljubivi svedoci? Čak i kada bismo pretpostavili da su Velid ibn Jezid i Muhammed ibn Harun činili ta dela, to sa nama kao muslimanima nema nikakve veze, jer svako nosi svoj teret. Mnogi svetski vladari kroz istoriju činili su razvrat, pa zašto se neprijatelji islama usredsređuju baš na kritiku emevijskih i abasijskih halifa?"]},{"slug":"Pitanje-sihra-i-Poslanik","chunks":["Poslanikova ﷺ sačuvanost odnosi se na dostavljanje objave, i to je ono što je Allah obećao i što potvrđuju čuda koja je pokazao. Ono što se tiče ovosvetskih stvari, zbog kojih nije ni poslat, poput bolesti, ne ulazi u tu sačuvanost. Ibn el Kassar je sihr opisao kao vrstu bolesti. Poslanik ﷺ je Allahovom voljom potpuno ozdravio, a sihr na njega nije bitno uticao. Mnogi, uključujući i šije, tvrde da je Poslanik ﷺ bio pod dejstvom sihra. To jeste tačno, ali ne na način na koji oni to razumeju. Šta o tome kaže Fethul bari U Fethul bariju, komentaru Sahiha Buharije, tom 17, str. 602 603, stoji: El Mazari je rekao: Pojedini novotari odbili su da prihvate ovaj hadis, tvrdeći","da on umanjuje stepen poslanstva Muhammeda ﷺ… Poslanik je sačuvan sa strane dostavljanja poslanice, kako mu je Allah obećao, a o tome svedoče i čuda koja je pokazao. A ono što je vezano za stvari ovoga sveta, zbog kojih nije ni poslat, od toga nije sačuvan, kao što su, na primer, bolesti i nemoć. Sačuvanost poslanika Muhammeda ﷺ od šejtanske štete odnosi se, dakle, upravo na potvrđivanje poslanice. Ibn el Kassar je dejstvo sihra opisao kao vrstu bolesti. Dodatni argument Ako pojedeš sedam adžva hurmi, to će te sačuvati od sihra, uz nadu da ćeš ozdraviti. A Poslanik je Allahovom voljom potpuno ozdravio, i sihr na njega nije bitno uticao, nego je to bilo više nalik bolesti."]},{"slug":"Pohod-na-Benu-Mustalik","chunks":["To što predaja ne spominje raniji poziv ne znači da poziv do njih nije doprla. Iznenađenje u predaji je vremensko, a ne uzročno. Poziv islama do Benu Mustalika je doprao, jer su oni rođaci Evsa i Hazredža, a mnogi iz Huzaa primili su islam. Uz to, Benu Mustalik nisu bili miroljubivi: bili su saveznici Kurejšija, učestvovali su u Bici na Uhudu, okupljali su vojsku protiv Poslanika ﷺ, a njihov vođa je otvoreno izjavio da će ga zatrti. Predaja o kojoj je reč Pričao nam je Alija ibn el Hasan, obavestio nas je Abdullah, obavestio nas je Ibn Avn, rekavši: Pisao sam Nafiju, a on mi je pisao da je Poslanik ﷺ napao Benu Mustalik dok su bili nesvesni, a njihova","stoka se pojila na pojilištu, pa je pobio njihove borce, a njihovu decu zarobio, i toga dana zarobio je Džuvejriju. To mi je preneo Abdullah ibn Omer, koji je bio u toj vojsci. Prvo ćutanje predaje ne znači da poziv nije doprao Poziv Poslanika ﷺ doprao je do arapskih plemena, postao poznat i očigledan među njima, tako da nikome nije preostalo opravdanje. Nije preostalo ništa osim islama. Ako se nisu odazvali i nisu se predali, onda im nije preostalo ništa osim borbe. Poslanik ﷺ bi kretao u pohod i sačekao, pa ako bi čuo ezan, ne bi napadao. Ako ga ne bi čuo, to je bio znak da je reč o zemlji mnogoboštva, pa bi ih napao bez upozorenja, jer","je opšte upozorenje njima i drugima već prethodilo. Nakon što se uverio u vest, Poslanik ﷺ je pozvao ashabe i požurio sa polaskom. Krenuo je dve noći pre kraja ša'bana. Allahov Poslanik je stigao do El Murejsija, poredao svoje ashabe i naredio im da napadnu kao jedan čovek. Pobeda je ostvarena, a mnogobošci su poraženi. Šta „iznenađenje\" zapravo znači Tvrdnja da su napadnuti bez povoda je zabluda, jer između njih borbe nije ni bilo, nego ih je napao na pojilištu. Kao što u verodostojnoj predaji stoji: Allahov Poslanik je napao Benu Mustalik dok su bili nesvesni. To je slično kao kada bi se reklo: „Egipat je iznenadio Jevreje i probio Bar Levovu liniju 1973. godine\". Takva rečenica sama po sebi","nije potpuna, jer prenosilac nije spomenuo egipatski poraz 1967. godine niti neprijateljstvo između njih. To što prenosilac nije spomenuo neki događaj ne obavezuje nas da priču poričemo. „Borba protiv njih iznenada\" ne znači da su napadnuti bez znanja o islamu ili bez počinjenog greha. Iznenađenje je ovde vremensko. Ono se odnosi isključivo na vremensko iznenađenje, koje nema veze sa uzrokom. Muslimani su ih jednostavno zatekli u njihovim domovima dok su bili nesvesni. Drugo poziv islama je doprao do njih Islam je do njih doprao otkako je Allah poslao Muhammeda ﷺ. Benu Mustalik su rođaci Evsa i Hazredža, muslimanskih ensarija Poslanika ﷺ. Njihov zajednički predak je Amr ibn Amir ibn Harisa ibn Imrul Kajs. Kako poziv ne bi doprao do njih,","kada su svi njihovi rođaci primili islam? Mnogi iz plemena Huzaa primili su islam, među njima Amina bint Halef, koja je sa svojim mužem izbegla u Abesiniju još pre nego što je Poslanik ﷺ ušao u Medinu. Zatim Atika Umm Ma'bed el Huzaijja, Mu'teb ibn Avf, koji je bio na Bedru, i Nafi ibn Bedil, koji je poginuo kao šehid na Bir Meuni. Treće Benu Mustalik nisu bili miroljubivi Oni su okupljali vojske protiv Allahovog Poslanika ﷺ. Benu Mustalik bili su pristalice Kurejšija u okviru saveza plemena koja su se udružila da se bore protiv Poslanika ﷺ i muslimana. Zajedno sa Kurejšijama učestvovali su u Bici na Uhudu i borili se protiv muslimana. Njihov vođa je izjavio: Čuo sam da","ste se okupili protiv ovog čoveka, misleći na Allahovog Poslanika, pa ću krenuti među svoj narod, i ko mi se pokori, neka nam ruka bude jedna, sve dok ga ne zatremo. Zaključak Benu Mustalik nisu bili miroljubivi. Učestvovali su na Uhudu, okupljali su vojske, a njihov vođa je otvoreno izjavio da namerava da zatre Allahovog Poslanika ﷺ. Mit o tome da su bili „bezbedni i miroljubivi\" potpuno je neosnovan."]},{"slug":"Sijski-mehdi-i-Aisa","chunks":["Medžlisi u Biharul envaru prenosi predaju u kojoj Ebu Džafer navodi da će njihov Kaim, kada se pojavi, dati da mu se dovede Aiša, radijallahu anha, nakon što bude oživljena, kako bi nad njom izvršio šerijatsku kaznu i osvetio se umesto Fatime. Ista predaja nalazi se i u delu Kitabur red'a i u Ilelu š šerai od šejha Saduka. Time se otkriva kakav odnos prema majci vernika njihovi izvori zapravo utvrđuju. Medžlisi u Biharul envaru, 52/314 315, prenosi: Od Abdur Rahima el Kasira, koji je rekao: Rekao mi je Ebu Džafer, mir neka je na njega: Kada ustane naš Kaim, biće mu vraćena Humejra, kako bi nad njom izvršio šerijatsku kaznu i kako bi se osvetio umesto Muhammedove kćerke Fatime,","mir neka je na nju. Rekao sam: Neka sam ti žrtva, a zašto bi nad njom izvršio kaznu? Rekao je: Zbog njene klevete na Ibrahimovu majku. Rekao sam: Pa kako to da je Allah odložio za Kaima, mir neka je na njega? Rekao mu je: Uzvišeni Allah poslao je Muhammeda ﷺ kao milost, a Kaima, mir neka je na njega, poslao je kao osvetu. Izvor: Biharul envar, Medžlisi, 52/314 315. Humejra je nadimak kojim se u šijskim predajama označava Aiša, radijallahu anha. Izraz „Kaim\" odnosi se na njihovog očekivanog mehdija. Ista predaja nalazi se i u delu Kitabur red'a šejha Ahmeda ibn Zejnudina el Ahsaija. Isti izveštaj nalazi se i u delu Ilelu š šerai šejha Saduka, str. 303 304,","hadis 10."]},{"slug":"Slaba-predaja-o-dodiru","chunks":["Predaja je slaba i po senedu i po tekstu. U njenom lancu nalazi se Hanzala es Sedusi, opisan kao slab i pometen prenosilac kojeg odbacuje većina hadiskih učenjaka. Ahmed ibn Hanbel za njega je rekao da izmišlja hadise i da prenosi neobične stvari, a Salih ibn Ahmed ibn Hanbel da prenosi izmišljene hadise od Enesa. Delo El Metalibul alije ocenjuje predaju slabom upravo zbog Hanzalinе slabosti. O kojoj je predaji reč Pojedini prigovarači, naročito iz šijskih polemičkih krugova, navode predaju pripisanu Enesu ibn Maliku, u kojoj se tvrdi da je Poslanik ﷺ postupio na način koji mu se pripisuje nakon što ga je jedna žena zamolila da joj potare lice i uputi dovu za nju. Ovaj tekst pokazuje da je","ta predaja slaba i po senedu i po tekstu, da se u njoj nalazi poznati izmišljač Hanzala es Sedusi, i da oslanjanje prigovarača na nju razotkriva njihovo nemarenje za klasičnu hadisku metodologiju. Sam tekst predaje ocenjen je slabim, a u njemu se nalazi Hanzala es Sedusi, opisan kao slab i pometen prenosilac, kojeg odbacuje većina hadiskih učenjaka. Mana u senedu Hanzala es Sedusi Ahmed ibn Hanbel je izjavio: „Taj izmišlja hadise, prenosi neobične stvari.\" Zabeležene kritike uključuju sledeće: 1. Prenosio je neobične izveštaje o Poslanikovoj ﷺ praksi koji se ne nalaze u verodostojnim zbirkama. 2. Salih ibn Ahmed ibn Hanbel izjavio je: „Slab hadis, prenosi izmišljene hadise od Enesa.\" 3. Većina hadiskih učenjaka oslabila je njegove predaje i namerno ih","odbacila. Što se tiče toga što ga je Ibn Hibban ocenio pouzdanim, takva ocena ne jamči apsolutnu pouzdanost i nadjačana je saglasnošću učenjaka. Saglasnost učenjaka o slabosti ove predaje Delo El Metalibul alije ocenjuje je ovako: „Slaba, zbog slabosti Hanzale.\" Saglasnost učenjaka, dakle, jasno odbacuje ovu predaju zbog poznatog izmišljača u njenom lancu."]},{"slug":"Talha-je-zeleo-da-ozeni-Aisu","chunks":["Delo na koje se šije pozivaju samo je pripisano Ibn Abbasu, radijallahu anhu, i nije dokazano da ga je on napisao. Uz to, sam navod u toj knjizi nema sened. Sujuti donosi pet predaja tog navoda i sve su slabe. Prenosilac u tim lancima je Mihran ibn Ebul Attar, kojeg hadiski učenjaci smatraju lažljivcem, a u drugoj verziji Muhammed ibn Mervan es Suddi es Sagir, kojeg je niz imama proglasio lažljivcem i slabim. Šije navode takozvani Tefsir Ibn Abbasa. Ta knjiga, međutim, nije verodostojna. Ona je plemenitom ashabu samo pripisana, a nije dokazano da ju je on napisao. Sened tog navoda ne postoji ni u samoj knjizi Dželadudin es Sujuti donosi pet predaja tog navoda. Sve su slabe. Prenosilac u","tim lancima jeste Mihran ibn Ebul Attar, kojeg hadiski učenjaci smatraju lažljivcem. Ibn Hadžer o njemu kaže da je bio slabog pamćenja i da je grešio. Imam Ibn Ebu Hatim kaže da je mnogo grešio, a naročito kada je prenosio od Sufjana es Sevrija. Treba obratiti pažnju: reč je upravo o tom slučaju, jer u ovim lancima on prenosi od Sufjana es Sevrija. Sujuti taj navod donosi i na drugom mestu u svojoj knjizi. Ta verzija uopšte nema sened. Na drugim mestima u Sujutijevoj knjizi sened postoji, ali je i on, kao i obično, slab, jer sadrži još jednog slabog prenosioca, Muhammeda ibn Mervana es Suddija es Sagira. Imam Ibn el Dževzi, imam el Dževzedžani, imam el Esedi, Ibn Hibban,","imam Darekutni, imam Taberi i imam el Fesevi, Allah im se smilovao, nazvali su ga lažljivcem i slabim prenosiocem."]},{"slug":"Teravija-je-sunnet-a-ne-Omerova-novotarija","chunks":["Omer, radijallahu anhu, nije uveo teraviju. Sve što je učinio jeste da je male skupine koje su već klanjale u mesdžidu tokom ramazana objedinio u jednu veliku, iza jednog imama. Upravo tu upravnu odluku nazvao je „lepom novotarijom\", u jezičkom, a ne u šerijatskom smislu. Sam namaz traje od vremena Poslanika ﷺ, što potvrđuju predaje Ebu Zerra i Nu'mana ibn Bešira, a i šijski izvori, El Kafi i Tehzibul ahkam, prenose da je Poslanik ﷺ u ramazanu nakon jacije klanjao u mesdžidu, a ljudi za njim. Jedna od često ponavljanih optužbi šija protiv Omera, radijallahu anhu, jeste da je on uveo teraviju, koju sunije klanjaju tokom ramazana. Činjenica je, međutim, da je sve što je Omer, radijallahu anhu, učinio bilo","to da je male skupine ljudi, koji su već klanjali u mesdžidu tokom ramazana, objedinio u jednu veliku skupinu, kako bi klanjali za jednim imamom umesto za više različitih imama. Upravo je tu upravnu odluku nazvao „lepom novotarijom\", i to u jezičkom smislu. Omer nije nazvao novotarijom sam namaz, jer se taj namaz klanjao još od vremena Poslanika ﷺ. On kijam nije pretvorio iz pojedinačnog u zajednički čin ibadeta, niti ga je iz kućnog preneo u javni, u mesdžid, jer to nije ni imao potrebe da čini: ljudi su ga već klanjali u manjim skupinama, javno. Zajednički vid kijama bio je već ustaljen i u praksi i pre nego što se Omer, radijallahu anhu, pojavio u toj priči. Prvo dokazi","da se teravija klanjala nakon jacije Prema ispravnom mišljenju, vreme teravije u ramazanu počinje nakon jacije i traje do ezana za sabah. Muftija Aziz ur Rahman Usmani el Hanefi naveo je: „Ako se teravija klanja u poslednjem delu noći, ispravna je.\" Izvor: Fetava Darul ulum Deoband, tom 4, str. 210. Isti je naveo: „Nakon jacije svaki dobrovoljni namaz računa se kao tehedždžud, i za njega se dobija nagrada tehedždžuda.\" Izvor: Fetava Darul ulum Deoband, tom 4, str. 223. Šijski ajetolah Sejjid Ali Husein Sistani naveo je: „Vreme noćnog namaza počinje od sredine noći, prema poznatom mišljenju. Iako je bolje, nije nemoguće da vreme noćnog namaza počinje nakon jacije i traje do ezana za sabah.\" Izvor: Tevdihul mesail, str. 131. Predaja","Ebu Zerra Postili smo ramazan sa Allahovim Poslanikom ﷺ, i Poslanik ﷺ nas nije predvodio u kijamu sve dok nije preostalo sedam dana meseca, a onda nas je predvodio u kijamu dok nije prošla trećina noći. Zatim, kada je preostalo šest dana, nije nas predvodio. Kada je preostalo pet dana, predvodio nas je u kijamu dok nije prošla polovina noći. Rekli smo: Allahov Poslaniče, zašto nas ne predvodiš u kijamu do kraja noći? Rekao je: Ako čovek klanja sa imamom dok imam ne ode, to mu se piše kao da je celu noć proveo u namazu. Zatim, kada su preostala četiri dana, nije nas predvodio. Kada su preostala tri dana, poslao je po svoje kćeri i žene, okupio ljude, i","predvodio nas je u kijamu dok se nismo pobojali da ćemo propustiti el felah. Zatim nas do kraja meseca više nije predvodio u kijamu. Davud, jedan od prenosilaca, rekao je: Rekao sam: Šta je el felah? Rekao je: Sehur, obrok pred zoru. Izvor: Sunen Nesai, tom 2, str. 303 304, br. 1365, verodostojan prema Zubejru Ali Zaiju; Džami Tirmizi, tom 2, str. 230 231, br. 806, hasen sahih prema Tirmiziju; Sunen Ebu Davud, str. 237, br. 1375, verodostojan prema Albaniju; Sunen Ibn Madže, tom 1, br. 1327. Predaja Nu'mana ibn Bešira Čuo sam Nu'mana ibn Bešira na minberu u Himsu kako kaže: Klanjali smo kijam sa Allahovim Poslanikom ﷺ tokom ramazana, dvadeset treće noći, dok nije prošla trećina noći, zatim","smo klanjali kijam sa njim dvadeset pete noći, dok nije prošla polovina noći, a zatim smo klanjali kijam sa njim ﷺ dvadeset sedme noći, dok nismo pomislili da ćemo propustiti el felah, a tako su nazivali sehur. Izvor: Sunen Nesai, tom 2, str. 458, br. 1607, hasen prema Zubejru Ali Zaiju; Salatut teravih, str. 9 10, sened verodostojan prema Albaniju. Imam Hakim je nakon navođenja ovog hadisa rekao: U ovoj predaji je jasan dokaz da je klanjanje teravije u mesdžidima muslimana utvrđeni sunnet. Alija ibn Ebu Talib, radijallahu anhu, podsticao je Omera, radijallahu anhuma, da uspostavi taj sunnet, sve dok ga on nije i uspostavio. Izvor: Mustedrek Hakim, tom 1, str. 607, br. 1608. Drugo teravija u šijskim predajama Alija","ibn Ibrahim prenosi od Muhammeda ibn Isaa ibn Ubejda, od Junusa, od Ebul Abbasa el Bakbaka i Ubejda ibn Zurare: Ebu Abdullah, mir neka je na njega, rekao je da bi Allahov Poslanik ﷺ povećavao svoj namaz tokom ramazana. Nakon jacije, klanjao bi još. Ljudi bi iza njega ustajali za namaz, ali bi on ušao unutra i ostavio ih. Zatim, kada bi izašao, oni bi došli i stali iza njega, a on bi ih ostavio i ušao unutra, i to više puta. Izvor: El Kafi, tom 4, str. 94. Medžlisi je predaju ocenio verodostojnom u Mir'atul ukulu, tom 16, str. 378. Bio sam kod Ebu Abdullaha, mir neka je na njega, kada je upitan da li se dobrovoljni namaz povećava","tokom ramazana. Rekao je: Da, Allahov Poslanik ﷺ povećavao bi svoj namaz tokom ramazana. Nakon jacije klanjao bi još u svom mesdžidu. Ljudi bi se okupljali iza njega za namaz, ali kada bi im se broj povećao, ušao bi u svoju kuću i ostavio ih. Kada bi se ljudi razišli, vratio bi se u mesdžid i klanjao kao i pre, a kada bi se broj ljudi iza njega povećao, ostavio bi ih i ponovo ušao u svoju kuću. Izvor: Tehzibul ahkam, tom 3, str. 68. Jaciju su ljudi nazivali i namazom el atme, kako stoji u Sahihu Buharije, tom 1, str. 337, br. 564. Navedene šijske predaje jasno dokazuju da bi Poslanik ﷺ klanjao nakon jacije u mesdžidu, i da","bi, kada bi se okupilo mnoštvo, otišao svojoj kući, a zatim se ponovo vraćao u mesdžid kada bi se mnoštvo smanjilo. Za razliku od sunijskih hadisa, te predaje tu praksu Poslanika ﷺ ne ograničavaju na tri ili četiri dana. Predaja u Tehzibu koristi izraz „mirar\", to jest više puta, čime se ukazuje da noćni namaz u ramazanu u džematu nije predvodio jednom ili dvaput, nego mnogo puta. Vredi obratiti pažnju: da je namaz u džematu nakon jacije bio zabranjen, kako šije tvrde, zašto Poslanik ﷺ nije to prekinuo već prvi put? Uz to, njegov postupak ostavljanja ljudi i odlaska u kuću bio je vezan za povećanje broja okupljenih, što pokazuje da mu, da je broj bio mali, nastavak namaza ne","bi bio sporan. Treće odgovor na predaju Zejda ibn Sabita Šije navode predaju u kojoj Poslanik ﷺ kaže: „Klanjajte taj namaz u svojim kućama, jer je najbolji namaz onaj koji čovek klanja u svojoj kući, osim propisanog namaza.\" Odgovor je u samom hadisu. Razlog koji je Poslanik ﷺ naveo za prekidanje noćnog namaza u džematu jeste taj što se pobojao da bi taj namaz mogao postati obavezan, pa ga ljudi ne bi mogli izvršavati. Vredi razmisliti o sledećem: Poslanik ﷺ je, i nakon što je znao da mu se ljudi priključuju u džematu, taj namaz u mesdžidu u džematu nastavio tri ili četiri dana, i prekinuo ga je tek kada se mnoštvo povećalo. Zašto nije prekinuo već prvog dana, kada","je primetio manju skupinu? To ukazuje na to da razlog prekidanja nije bio u tome što je sa tim namazom ili sa džematom nešto sporno, nego u njegovoj raširenosti. Da je noćni namaz u džematu bio zabranjen, Poslanik ﷺ ga ne bi nastavljao tri ili četiri dana, nego bi ljude već prvog dana izričito obavestio da se tako ne klanja. Imam Ibn Redžeb el Hanbeli Poslanik ﷺ podsticao je i podstrekivao ljude na kijam u ramazanu. U njegovo vreme ljudi su kijam klanjali u mesdžidu, u razdvojenim skupinama i pojedinačno, a on ﷺ je svoje ashabe predvodio u kijamu u ramazanu više noći. Zatim je to prestao činiti, jer se pobojao da bi im to moglo biti propisano kao obaveza,","pa je ne bi mogli izvršavati. Nakon njegove smrti ﷺ te bojazni više nije bilo. Izvor: Džamiul ulumi vel hikem, str. 597 598, hadis br. 28. Šejhul islam Ibn Tejmijje Što se tiče kijama u ramazanu, Allahov Poslanik ﷺ ga je uveo svom ummetu i predvodio ih je u namazu više noći, jer su u njegovo vreme klanjali i u džematu i pojedinačno. Ali nije ustrajao u tome da ih predvodi u jednom džematu, da im to ne bi bilo propisano kao obaveza. Kada je Poslanik ﷺ preselio, šerijat je bio utvrđen. Kada je Omer, radijallahu anhu, postao halifa, objedinio ih je iza jednog imama, Ubejja ibn Ka'ba, koji je ljude objedinio u jedan džemat po Omerovoj naredbi. Omer je","bio jedan od pravednih halifa, o kojima je Poslanik ﷺ rekao: Držite se moga sunneta i puta pravednih halifa nakon mene, čvrsto ga se držite. Ono što je učinio, dakle, jeste sunnet. Izvor: Medžmuul fetava, tom 11, str. 498. Imam Ibn Abdul Berr To ukazuje na to da je klanjanje kijama u ramazanu jedan od sunneta Poslanika ﷺ, i da je pohvalno i podsticano. Nije ga uveo Omer ibn el Hattab, nego je oživeo ono što je Allahov Poslanik ﷺ voleo i odobravao. Poslanika ﷺ je od redovnog činjenja toga sprečila jedino bojazan da bi to njegovom ummetu bilo propisano kao obaveza. On je prema svom ummetu bio blag i milostiv. Omer je od Allahovog Poslanika ﷺ znao da se","obaveze nakon njegove smrti neće povećavati ni smanjivati, pa je tu praksu oživeo i naložio je ljudima. To se dogodilo 14. godine po Hidžri, i Omer ima čast da je onaj koji je taj sunnet oživeo. Izvor: Et Temhid, tom 8, str. 108 109. Što se tiče tvrdnje da je dobrovoljni namaz bolje klanjati kod kuće, to ne čini dobrovoljni namaz u mesdžidu zabranjenim. I same šije klanjaju dobrovoljne namaze nakon obaveznih u mesdžidu. Jedino što se na osnovu te predaje može tvrditi jeste da je dobrovoljni namaz kod kuće bolji i vredniji. Na primer, učenje duže sure u noćnom namazu je bolje, ali to ne čini učenje kratke sure zabranjenim. Četvrto dokazi da se dobrovoljni namaz klanjao u džematu","Šije tvrde da se dobrovoljni namazi ne mogu klanjati u džematu. Ta tvrdnja je neosnovana. Noćni namaz bio je Poslaniku ﷺ propisan kao obaveza u Meki, objavom sure El Muzzemmil, a ta naredba je nakon godinu dana derogirana, nakon čega je noćni namaz postao dobrovoljan. Sa'd ibn Hišam upitao je Aišu, radijallahu anha: Obavesti me o noćnom namazu Allahovog Poslanika ﷺ. Aiša je rekla: Zar nisi učio suru „O ti, umotani\"? Rekao je: Jesam. Rekla je: Uzvišeni i Slavljeni Allah učinio je obaveznim obavljanje noćnog namaza na početku te sure. Allahov Poslanik ﷺ i njegovi ashabi obavljali su ga godinu dana. Allah je završni deo te sure zadržao dvanaest meseci na nebu, sve dok nije objavio završne ajete koji su","tu obavezu olakšali, pa je noćni namaz postao dobrovoljan nakon što je bio obavezan. Izvor: Sahih Muslim, tom 2, str. 259, br. 746. Uz to, evo predaja u kojima je Poslanik ﷺ i sam predvodio dobrovoljni namaz u džematu ili odobrio onima koji su ga tako klanjali. Itban ibn Malik es Salimi rekao je: Došao sam Allahovom Poslaniku ﷺ i rekao: Allahov Poslaniče, vid mi slabi, a bujica dolazi i sprečava me da stignem do mesdžida svog naroda. Šta misliš, možeš li doći i klanjati u mojoj kući na mestu koje bih potom uzeo kao mesto za namaz? Rekao je: Učiniću to. Sutradan su Allahov Poslanik ﷺ i Ebu Bekr, radijallahu anhu, došli… Pokazao sam mu mesto gde sam želeo","da klanja, pa je Allahov Poslanik stao, a mi smo se poredali iza njega, i predvodio nas je u dva rekata. Izvor: Sunen Ibn Madže, tom 1, str. 493 494, br. 754, verodostojan prema Zubejru Ali Zaiju; Sahih Buhari, tom 2, str. 166, br. 1186. Od Enesa: Allahov Poslanik ﷺ nam je došao, a u našoj kući nije bilo nikoga osim mene, moje majke i moje tetke Umm Haram. Rekao je: Ustanite da vas predvodim u namazu, a nije bilo vreme propisanog namaza. Predvodio nas je u namazu. Izvor: Sahih Muslim, tom 2, str. 163, br. 1501, poglavlje: Dozvoljenost klanjanja dobrovoljnog namaza u džematu. Enes ibn Malik je rekao: Moja nana Mulejka pozvala je Allahovog Poslanika ﷺ na jelo koje","je sama pripremila. Jeo je od njega i rekao: Ustanite, predvodiću vas u namazu. Uzeo sam svoju hasuru, oprao je vodom jer je od duge upotrebe potamnela, i Allahov Poslanik ﷺ je stao na nju. Ja i siroče poredali smo se iza njega, a starica je stala iza nas. Allahov Poslanik ﷺ nas je predvodio i klanjao dva rekata, a zatim otišao. Izvor: Sahih Buhari, tom 1, str. 255 256, br. 380; Sahih Muslim, tom 2, str. 162, br. 1499. Od Džabira, radijallahu anhu, da je Ubejj ibn Ka'b, radijallahu anhu, došao Allahovom Poslaniku ﷺ i rekao: Sinoć sam, u ramazanu, nešto učinio. Allahov Poslanik je rekao: Šta si učinio? Rekao je: Neke žene su došle u moju kuću i","rekle: Ne znamo mnogo Kur'ana, pa ćemo klanjati iza tebe i slušati Kur'an. Pa sam ih predvodio u osam rekata i klanjao vitr. Allahov Poslanik ﷺ je ćutao, kao da je to odobrio. Izvor: Musned Ebu Ja'la, tom 2, str. 359, br. 1803; Medžmeuz zevaid, tom 2, str. 74, sened hasen prema Hejsemiju. Aiša, radijallahu anha, rekla je: Tokom ramazana ljudi su noću klanjali u Poslanikovom ﷺ mesdžidu, u razdvojenim skupinama. Ako bi čovek naučio nešto Kur'ana napamet, predvodio bi skupinu od pet ili šest ljudi u tom namazu. Jedne od tih noći Poslanik ﷺ mi je naredio da mu pripremim prostirku za namaz ispred moje sobe, i nakon što je klanjao jaciju, izašao je. Po njegovom dolasku u mesdžid,","ljudi su se okupili oko njega, pa ih je predvodio u dugom noćnom namazu. Izvor: Musned imama Ahmeda, tom 43, str. 332 334, br. 26307, sahih li gajrihi. Allahov Poslanik ﷺ izašao je i video da ljudi u uglu mesdžida klanjaju tokom ramazana. Upitao je: Ko su ovi ljudi? Rečeno mu je da su to ljudi koji nisu naučili Kur'an, ali da Ubejj ibn Ka'b klanja, a oni klanjaju za njim. Poslanik ﷺ je rekao: Dobro su postupili, i lepo je to što su učinili. Izvor: Es Sunenul kubra, Bejheki, tom 2, str. 697, br. 4611, mursel hasen prema Bejhekiju; Sunen Ebu Davud, tom 2, str. 141 142, br. 1377, hasen prema Zubejru Ali Zaiju. Ibn Tejmijje o dobrovoljnom namazu","u džematu Dobrovoljni namazi koji se klanjaju u džematu dele se na dve vrste. Prvu je sunnet klanjati u džematu, poput namaza prilikom pomračenja, namaza za kišu i kijama u ramazanu, odnosno teravije. Oni se uvek klanjaju u džematu, kao što je sunnet. Druga vrsta se ne klanja u džematu, poput noćnog namaza, redovnih sunneta, duha namaza i namaza pri ulasku u mesdžid. Ali ako se povremeno klanjaju u džematu, to je dozvoljeno. Što se tiče stalnog klanjanja u džematu, to nije propisano. Izvor: Medžmuul fetava, tom 23, str. 413 414. Šijski izuzetak za namaz u džematu I same šije prave izuzetak za klanjanje pojedinih dobrovoljnih namaza u džematu. One smatraju da se namaz za kišu, koji nije obavezan, može","klanjati u džematu. Šijski ajetolah Sejjid Ali el Husejni es Sistani naveo je: Pohvalni namazi, iz predostrožnosti, ne mogu se klanjati u džematu ni u kojem slučaju, osim namaza za kišu ili namaza koji su nekada bili obavezni, a kasnije postali pohvalni, poput bajram namaza. Ne bi im, dakle, trebalo biti sporno to što sunije, sledeći sunnet Poslanika ﷺ, tokom ramazana klanjaju teraviju u džematu. Peto Omer je izraz „novotarija\" upotrebio u jezičkom smislu Abdur Rahman ibn Abdul Kari rekao je: Izašao sam sa Omerom ibn el Hattabom jedne noći u ramazanu u mesdžid, i zatekli smo ljude kako klanjaju u različitim skupinama. Čovek klanja sam, ili čovek klanja sa malom skupinom iza sebe. Omer je rekao: Po mom mišljenju,","bolje bi bilo da ih okupim iza jednog učača. Pa je odlučio da ih okupi iza Ubejja ibn Ka'ba. Zatim sam druge noći ponovo izašao sa njim, a ljudi su klanjali za svojim učačem. Omer je tada primetio: Kako je lepa ova novotarija, ali je namaz koji ne obavljaju, nego u to vreme spavaju, bolji od ovoga koji obavljaju. Mislio je na namaz u poslednjem delu noći. Izvor: Sahih Buhari. Omer, dakle, novotarijom nije nazvao sam namaz, jer se on klanjao još od vremena Poslanika ﷺ, nego svoju upravnu odluku da sve razdvojene džemate objedini u jedan jedinstveni džemat iza jednog imama. Ovaj tekst prenosi glavne dokaze iz izvornog, znatno opširnijeg izlaganja. Izvorni tekst sadrži i dalju raspravu tačku po","tačku sa šijskim sajtovima."]},{"slug":"Tvrdnja-da-je-Ibnul-Kajjim-dozvolio-samozadovoljavanje","chunks":["Ibnul Kajjim ništa od toga nije dozvolio. Njegov tekst iz Bedaiul fevaida navodi tuđe mišljenje, a zatim ga izričito odbacuje rečima da je po njemu ispravno da to nije dozvoljeno, jer je Poslanik ﷺ onome ko ima strast, a ne može da se oženi, naredio post. Izraz „lakše je\" ne znači dozvolu, jer lakoća nečega uopšte nije merilo dozvoljenosti. Tekst koji sledi bavi se pravnim pitanjem intimne prirode i navodi se isključivo radi tačnog prikaza onoga što je Ibnul Kajjim zaista napisao. Sadržaj primedbe Šije tvrde da je imam Ibnul Kajjim izdao fetvu kojom se muškarcu dozvoljava samozadovoljavanje pomoću izdubljene lubenice, testa, kipa ili nečeg sličnog. Tvrde i da je Ibnul Kajjim ženi dozvolio upotrebu veštačkog pomagala. Odgovor Ibnul Kajjim","ništa od toga nije dozvolio. Oni koji ovo iznose izvlače čovekove reči iz konteksta. Pogledajmo, dakle, njegove reči u celini. Ibnul Kajjim u svom delu Bedaiul fevaid kaže: Neki naši drugovi rekli su da joj je dozvoljeno da koristi pomagalo načinjeno od kože u obliku muškog polnog organa, ili nešto slično tome. Ispravno je, međutim, po mom mišljenju, da to nije dozvoljeno, jer je Poslanik ﷺ onome ko ima strast, a nije u mogućnosti da se oženi, naredio jedino post… A ako je reč o dečaku ili stranoj ženi, pokuđeno mu je da to čini, jer je to iskušenje za njega samog da učini ono što je zabranjeno i podsticaj njoj da to čini. A ako probuši lubenicu, testo, kožu","ili napravljenu figuru, pa u to unese, onda je to po pojedinostima koje smo već spomenuli. Izvor: Bedaiul fevaid, Ibnul Kajjim. Iz navedenog citata vidi se da je bilo onih koji su tvrdili da je ženi dozvoljena upotreba takvog pomagala, ali im Ibnul Kajjim odgovara i izdaje fetvu da muslimanki to nije dozvoljeno, nego da treba pribeći postu, kako nam je Allahov Poslanik ﷺ naredio. Zatim Ibnul Kajjim nastavlja i spominje slučaj pojedinih muškaraca koji probuše lubenicu, testo ili figuru. Tu se Ibnul Kajjim zaustavlja i kaže nam da je propis o tim muškarcima isti kao onaj podrobni propis koji je maločas spomenuo. Drugim rečima, ono što ti ljudi rade nije dozvoljeno, jer je Poslanik ﷺ onome ko ima strast","naredio post, a nije mu rekao da buši lubenicu. Napomena o izrazu „pokuđeno\" Vredi obratiti pažnju i na drugu Ibnul Kajjimovu rečenicu: A ako je odsutan od nje, budući da je taj čin dozvoljen i ne postaje zabranjen time što je zamišlja. A ako je reč o dečaku ili stranoj ženi, pokuđeno mu je da to čini, jer je to iskušenje za njega samog da učini ono što je zabranjeno i podsticaj njoj da to čini. U navedenom citatu imam Ibnul Kajjim kaže da je čoveku koji putuje i koji je odsutan od svoje žene dozvoljeno da nju i njeno telo zamišlja, jer je ona ipak njegova žena. Ali ako bi taj čovek zamišljao telo strane žene ili telo dečaka,","onda je to nešto pokuđeno, jer podstiče na zabranjeno. Treba znati da izraz „pokuđeno\" (mekruh) kod Ibnul Kajjima i njemu sličnih znači: zabranjeno. Izraz „lakše je\" ne znači dozvolu Postoji još jedna Ibnul Kajjimova rečenica koju su šije pogrešno razumele. Ibnul Kajjim na kraju izlaganja kaže: „To je lakše nego samozadovoljavanje rukom.\" Šije misle da ta rečenica muškarcu dozvoljava ono što je opisano, zato što je lakše od samozadovoljavanja. Odgovaramo da ta rečenica nije dokaz da je Ibnul Kajjim to dozvolio. Lakoća ili težina nečega uopšte nije merilo dozvoljenosti ili zabranjenosti. Evo nekoliko primera koji tu misao pojašnjavaju. 1. Blud je lakši od braka, jer brak nosi veliku odgovornost. Znači li to da je blud dozvoljen zato što je lakši?","Ne. 2. Namerno prekidanje posta tokom dana u ramazanu mnogo je lakše od posta. Znači li to da je namerno prekidanje posta u ramazanu dozvoljeno? Ne. 3. Sticanje imetka nedozvoljenim putem mnogo je lakše od mukotrpnog sticanja dozvoljenog imetka. Znači li to da je nedozvoljena zarada dozvoljena? Ne. Lakoća nečega, dakle, nije dokaz njegove dozvoljenosti."]},{"slug":"Tvrdnja-da-je-Omer-pio-vino","chunks":["Predaju prenosi Zuhri, a on nije živeo u Omerovo vreme, niti ga je video, niti je od njega išta čuo. Omer je preselio 23. godine po Hidžri, a Zuhri je rođen nakon 50. godine. Sened je, dakle, prekinut. Uz to, reč nebiz u arapskom jeziku ne znači nužno opojno piće, nego voće natopljeno u vodi. Ako ne opija, dozvoljeno je, a ako uskisne i opija, zabranjeno je. Sadržaj primedbe Šije tvrde da je Omer ibn el Hattab pio alkohol, i to dokazuju sledećom predajom: Od Ma'mera, od Zuhrija, da su Omeru ibn el Hattabu doneta dva plitka suda sa nebizom dok je bio na putu ka Šamu. Popio je iz jednog, a od drugog se okrenuo. Naredio je da se","onaj drugi ukloni, pa mu je donesen sutradan, a ono što je u njemu bilo postalo je nakiselo. Okusio ga je, a zatim rekao: Dobro je, dobro je, razblažite ga vodom. Odgovor na ovu primedbu Prvo sened je prekinut Ova predaja je slaba i istorijski nepotvrđena. Onaj ko je prenosi jeste Zuhri, a Zuhri ovde reči pripisuje Omeru ibn el Hattabu. Zuhri, međutim, nije živeo u vreme Omera ibn el Hattaba, niti ga je video, niti je od njega išta čuo, jer je Omer ibn el Hattab preselio 23. godine po Hidžri, a Zuhri je rođen nakon 50. godine. Zuhri, dakle, nije bio sa Omerom kada se događaj zbio, nije to od njega čuo, niti je bio sa njim na","putu ka Šamu. Ova predaja ima, prema tome, slab i prekinut sened. Poznato je učenjacima da su Zuhrijeve prekinute predaje veoma slabe, jer svoje prenošenje često uzima iz nepotvrđenog izvora. Pojedine šije kažu da je ovaj hadis dobar, ali ne znaju da se dobar hadis razlikuje od verodostojnog. Između te dve odrednice postoji razlika. Dobar hadis je nižeg stepena od verodostojnog, a u senedu dobrog hadisa može postojati mana koja vodi njegovoj slabosti. Zaključak je, dakle, da je verodostojan hadis višeg stepena od dobrog, pa je svaki verodostojan hadis ujedno i dobar, ali se svaki dobar hadis ne smatra verodostojnim. Drugo šta reč nebiz zapravo znači Mnogi danas pogrešno razumeju reč nebiz i misle da ona uvek označava opojno piće.","To je pogrešno razumevanje, jer nebiz u rečnicima arapskog jezika znači stavljanje slatkog ploda u vodu radi zaslađivanja njenog ukusa. Na primer, hurme ili grožđice stave se u vodu i tu se ostave, kako bi voda poprimila sladak ukus. Takvu vodu dozvoljeno je piti i u tome nema ničeg spornog. Međutim, ako se nebiz pokvari, pa mu miris i ukus postanu loši, on se pretvorio u opojno piće i mora se proliti. U tom slučaju zabranjeno ga je piti. Nebiz se, dakle, deli na dva stanja: svež nebiz koji nije prevreo, i nebiz koji je prevreo, postao mutan i opija onoga ko ga pije. Ako se vratimo rečnicima arapskog jezika, videćemo da jezikoslovci to dobro znaju i da razlikuju nebiz","koji ne opija od onoga koji opija. Ebu Hafs en Nesefi u svom delu Talbetut talebe, 1/70, kaže: A nebiz je da se hurme ili grožđice natope u vodi kako bi im se izvukla slast u vodu. To nije ono prvo, dakle nije opojno piće koje je spomenuo na početku svog izlaganja. El Himjeri u svom delu Šemsul ulum, deseti deo, str. 6464, kaže: Nebiz je poznat, a dolazi od glagola nebeze, što znači odbaciti nešto, jer se baca u posudu, a zatim se preko toga prelije voda. El Džubbi u delu Šerhu garibil mudevvene, 1/111, kaže: „Nebiz, sa slovom zal, uzet je od reči nebz, u značenju ostaviti nešto dok ne postane dobro.\" Jezikoslovac El Lubli u svom delu","Tuhfetul medždi s sarih, 1/262, navodi: Ebu Džafer je rekao: Znači ostavio sam ga da postane dobar. To je glagolska imenica u značenju trpnog prideva. Osnova reči nebz jeste bacanje i odbacivanje. Nebiz je po tome i nazvan, kao da je bačen u posude da bi se koristio. Poznati jezikoslovac Ibn Durejd u svom delu Džemheretul luga, 1/306, kaže: Nebeze nešto znači izbaciti to iz ruke. Nebiz je nazvan nebizom zato što su hurme bacane u ćup ili drugde. Jezikoslovac Ibn Faris u delu Mekajisul luga, peti deo, str. 380, kaže: „A nebiz: hurme se bace u posudu i preko njih se prelije voda.\" Na kraju vidimo da jezikoslovci nebiz dele na opojni i neopojni, a u oba slučaja naziva","se nebizom. Ako je opojan, njegovo pijenje je zabranjeno, a ako nije opojan, pijenje je dozvoljeno. Jezikoslovac Ibn Manzur u svom delu Lisanul arab, treći deo, str. 511, kaže: A nebiz je ono što je bačeno, i nebiz je ono što je bačeno od soka i slično tome. Spominjanje nebiza ponavlja se u hadisu, a to je ono što se pravi od pića od hurmi, grožđica, meda, pšenice, ječma i drugog. Kaže se: natopio sam hurme i grožđe, ako preko njih ostaviš vodu da postanu nebiz. I načinio sam nebiz, to jest načinio sam piće, bilo da opija ili ne, i to se naziva nebizom. Učenjak El Ezheri, koji je bio jezikoslovac i ujedno šafijski pravnik, a preselio je pre","više od hiljadu godina, u svom delu Tehzibul luga, četrnaesti deo, str. 318, kaže: Nebiz je poznat. Naziva se nebizom zato što onaj ko ga pravi uzme hurme ili grožđice i natopi ih, to jest stavi ih u posudu ili mešinu, prelije preko njih vodu i ostavi ih dok ne uzavru i ne prevriju, pa tako postanu opojni. Nebz znači bacanje. Ono što ne postane opojno dozvoljeno je, a ako opija, onda je zabranjeno. Učenjak El Ezheri, dakle, kaže da je nebiz dozvoljen sve dok je svež i dok ne opija. Ali ako vremenom prevrije i počne da opija, onda je zabranjen, jer se na taj način pretvorio u alkohol. Zato ćete, kada otvorite hadiske knjige, naći da je Poslanik","ﷺ dozvoljavao pijenje takvog nebiza sve dok se miris i ukus vode ne bi promenili, pokvarili ili prevreli. Poslanik ﷺ nam je takođe zabranio da natopljeno voće ostavljamo u vodi više dana, jer to vodi vrenju i kvarenju. Treće šta o nebizu stoji u šijskim knjigama U delu Tefsilu vesailiš ši'a ila tahsili mesailiš šeri'a, treći deo, str. 471, stoji: Svojim senedom od Ahmeda ibn Muhammeda ibn Isaa, od Alije ibn el Hakema, od Sejfa ibn Umejre, od Ebu Bekra el Hadramija, koji je rekao: Rekao sam Ebu Abdullahu, mir neka je na njega: Nebiz mi se prolio po odeći u kojoj klanjam. Rekao je: Da. Rekao sam: Kap nebiza kapnula je u posudu iz koje pijem. Rekao je: Da,","jer je osnova nebiza dozvoljena. Šijski učenjak Tusi u svom delu Ihtijaru ma'rifetir ridžal, prvi deo, str. 285, navodi: Prenosi se: Ušao sam kod Ebu Abdullaha, mir neka je na njega… Rekao sam: Video sam ga da pije nebiz. Rekao je: Misliš na opojno piće? Rekao sam: Da. Rekao je, Allah mu se smilovao: A Allahu nije teško da oprosti onome ko voli Aliju. U delu El Istibsar, prvi deo, str. 14, stoji: Upitao je Ebu Abdullaha, mir neka je na njega, o nebizu, pa je rekao: Dozvoljen je. Rekao je: Mi ga ostavimo i bacimo mutež i sve ostalo. Rekao je: Fuj, fuj, to je pokvareni nebiz. Rekao sam: Neka sam ti žrtva, na kakav nebiz misliš? Rekao je:","Stanovnici Medine požalili su se Allahovom Poslaniku na promenu vode i na to da im se priroda kvari, pa im je naredio da vodu prelivaju. Čovek bi naredio svom slugi da mu to učini, pa bi uzeo pregršt hurmi i bacio ih u mešinu, i nešto od toga bi pio, a nešto koristio za čišćenje. U delu Men la jahduruhul fekih, treći deo, str. 409, stoji: Prenosi se od Muhammeda ibn Ismaila ibn Bezia, koji je rekao: Pitao sam Ridaa, mir neka je na njega, o ženi koja je bila sklona pijenju nebiza i opila se, pa se u pijanom stanju sama udala za čoveka. Zatim je došla sebi i to poricala, a potom je pomislila da je on obavezuje,","pa se pobojala od njega i ostala sa tim čovekom u tom braku. Da li mu je ona dozvoljena, ili je brak nevažeći zbog pijanstva? Rekao je: Ako je ostala sa njim nakon što se osvestila, to je njen pristanak. Rekao sam: Da li je taj brak dozvoljen? Rekao je: Da. Sada pogledajmo poglavlje koje je šijski učenjak Kulejni posvetio propisu o pijenju nebiza. U delu El Kafi, četvrti deo, str. 417, stoji: Od Alije ibn Ibrahima, od njegovog oca, od Ibn Ebu Umejra, od Abdur Rahmana ibn el Hadždžadža, koji je rekao: Zatražio sam dozvolu za neke naše drugove da posete Ebu Abdullaha, mir neka je na njega, pa ga je upitao o nebizu. Rekao je: Dozvoljen je. Rekao","je: Pitao sam te samo o nebizu u koji se stavi mutež, pa uzavri, a zatim se slegne. Ebu Abdullah je rekao: Allahov Poslanik ﷺ rekao je: Svako opojno piće je zabranjeno. U delu El Kafi, četvrti deo, str. 415, stoji: Muhammed ibn Jahja, od Ahmeda ibn Muhammeda, od Muhammeda ibn Ismaila, od Hanana ibn Sedira, koji je rekao: Čuo sam čoveka kako govori Ebu Abdullahu, mir neka je na njega: Šta kažeš o nebizu? Ebu Merjem ga pije i tvrdi da si mu ti naredio da ga pije. Rekao je: Ebu Merjem je istinu rekao. Pitao me je o nebizu, pa sam ga obavestio da je dozvoljen, a nije me pitao o opojnom piću. Kako se vidi i iz","samih tih predaja, i u šijskim izvorima razlikuje se dozvoljeni nebiz od opojnog pića, koje je izričito zabranjeno. Upravo je to razlikovanje ono koje se prigovaračima gubi kada Omeru pripisuju pijenje alkohola."]},{"slug":"Tvrdnja-o-dzunupluku-u-mesdzidu","chunks":["Nijedna od predaja koje se navode iz sunijskih knjiga nije verodostojna. Njihove lance čine kufanski šijski prenosioci poput Atijje el Avfija, Salima ibn Ebu Hafse i Mahvela ibn Ibrahima, ili nepoznate ličnosti poput Haridže ibn Sa'da i Amre bint Ef'a. Prema hadiskom pravilu, kada novotar prenosi ono što ide u prilog njegovoj novotariji, njegova predaja se odbacuje. Istu predaju, međutim, šijski izvori prenose kao verodostojnu po sopstvenim merilima. Sadržaj primedbe Šije navode niz predaja iz sunijskih knjiga. Iznećemo te predaje, a zatim odgovoriti na njih. Prva predaja Pričao nam je Muhammed ibn Fadil, od Salima ibn Ebu Hafse, od Atijje, od Ebu Seida, koji je rekao: Allahov Poslanik je rekao Aliji: O Alija, nikome nije dozvoljeno da bude džunup u","ovom mesdžidu osim meni i tebi. Ovaj hadis je laž koju su izmislile rane šije koje su lagale, a zatim se on proširio po knjigama. Prenosilac koji je tu priču izmislio jeste Atijja ibn Sa'd el Avfi, koji je jedan od kufanskih šija i čiji je hadis slab. Ebu Seid koji se u predaji spominje nije ashab Ebu Seid el Hudri, nego šijski čovek po imenu el Kelbi, koji je lagao. Atijja el Avfi je sedeo sa el Kelbijem i nazivao ga Ebu Seidom, pa su ljudi pogrešno mislili da je reč o ashabu Ebu Seidu el Hudriju. Tu zabunu nam je razjasnio Ibn Hibban. Hadis je slab i mursel. Zatim, prenosilac Salim ibn Ebu Hafsa jeste slab šijski prenosilac.","Što se tiče prenosioca Muhammeda ibn Fadila, i on je šijski prenosilac. U pojedinim lancima naći ćete: „od Kesira en Nevva, od Atijje\", a Kesir en Nevva je slab i pokvaren šija. Postoji važno hadisko pravilo: ako novotar iznese nešto što se poklapa sa njegovom novotarijom, njegova predaja se odbacuje. Razlog je taj što je najverovatnije upravo novotar izmislio predaju da bi potvrdio svoju novotariju. Upravo su te šije izmišljale ovakve predaje da bi uzdigle Aliju ibn Ebu Taliba. Druga predaja Pričao nam je Ibrahim ibn Seid el Dževheri: pričao nam je Ismail ibn Ebu Uvejs: pričao mi je moj otac, od Hasana ibn Zejda, od Haridže ibn Sa'da, od njegovog oca Sa'da, koji je rekao: Allahov Poslanik je rekao","Aliji: Nikome nije dozvoljeno da bude džunup u ovom mesdžidu osim meni i tebi. Ta predaja je slaba, jer ju je preneo Haridža ibn Sa'd, koji je nepoznat. Sened te predaje nije jak. Prenosioca Ebu Uvejsa oslabili su mnogi učenjaci. Prenosilac Ismail ibn Ebu Uvejs jeste pouzdan, ali je grešio. Predaja je, dakle, veoma slaba. Treća predaja Pričao nam je El Kasim ibn Muhammed ed Dellal u Kufi, od Mahvela ibn Ibrahima, od Abdul Džebbara ibn el Abbasa, od Ammara ed Duhnija, od Amre bint Ef'a, od Umm Seleme, koja je rekla: Allahov Poslanik je rekao: Ne priliči nikome da bude džunup u ovom mesdžidu osim meni i Aliji. Ta predaja je već u osnovi slaba. Onaj ko je prenosi","jeste El Kasim ibn Muhammed ed Dellal el Kufi, a on je slab. Amra bint Ef'a je nepoznata. Prenosilac Mahvel ibn Ibrahim jeste kufanski rafidija koji je mrzeo Ebu Bekra es Siddika. Prenosilac Abdul Džebbar ibn Abbas jeste šija, a većina učenjaka ga je oslabila. Četvrta predaja Bejheki prenosi svojim senedom od Umm Seleme, koja je rekla: Allahov Poslanik je izašao, uputio se ka ovom mesdžidu i rekao: Ovaj mesdžid nije dozvoljen onome ko je džunup niti ženi u mesečnom pranju, osim Allahovom Poslaniku, Aliji, Fatimi, Hasanu i Husejnu. Imena sam vam jasno naveo da ne biste zalutali. Ta predaja je veoma slaba. Preneo ju je Mahdudž ed Dehli, koji je nepoznat. Preneo ju je i Ebul Hattab el Hidžri,","koji je nepoznat. A od njih ju je preneo Muhammed ibn Junus ibn Musa, koji je optužen za izmišljanje hadisa. Uz to, ova predaja u pojedinim svojim lancima spominje i žene Poslanika ﷺ, ali su oni koji lažu namerno skratili predaju da bi odgovarala njihovim prohtevima i da bi ženama Poslanika ﷺ oduzeli svaku vrednost. Peta predaja Sujuti prenosi od Ebu Rafija da je Poslanik održao govor ljudima i rekao: Allah je naredio Musau i Harunu da svom narodu obezbede kuće, i naredio im je da niko ko je džunup ne prenoći u njihovom mesdžidu, i da se u njemu ne prilazi ženama, osim Harunu i njegovom potomstvu. A nikome nije dozvoljeno da u ovom mom mesdžidu prilazi ženama, niti","da u njemu prenoći onaj ko je džunup, osim Aliji i njegovom potomstvu. Ta predaja je već u osnovi laž i izmislile su je rane šije. Albani, Adnan el Arur i drugi izdali su fetvu da je ta predaja laž. Njen sened ima tri problema: 1. Muhammed ibn Ubejdullah ibn Ebu Rafi, šija koji odbacuje hadis. 2. Mahvel ibn Ibrahim, kufanski rafidija koji je mrzeo Ebu Bekra es Siddika. 3. Abdur Rahman ibn el Esved el Jaškuri, nepoznat prenosilac. Te predaje izmislile su rane šije, a po sunijskim hadiskim pravilima one su slabe. Šije se, međutim, tim predajama ponose i smatraju ih vrlinama Alije ibn Ebu Taliba. Šesta predaja Obavestio nas je Omer ibn Ahmed, od Abdullaha ibn Ebu Davuda,","od Jahjaa ibn Hatima el Askerija, od Bišra ibn Mihrana, od Šerika, od Osmana ibn el Mugire, od Zejda ibn Vehba, od Abdullaha ibn Mes'uda, koji je rekao: Allahov Poslanik nam je došao jedne noći dok smo bili u mesdžidu, a među nama je bila skupina ashaba: Ebu Bekr, Omer, Osman, Hamza, Talha, Zubejr i skupina ashaba, nakon što sam klanjao jaciju. Rekao je: Kakva je ovo skupina? Rekli su: Allahov Poslaniče, sedeli smo razgovarajući, neki od nas su hteli da klanjaju, a neki su spavali. Rekao je: Niko neka ne spava u mom mesdžidu. Idite svojim kućama, pa ko želi da klanja, neka klanja u svojoj kući, a ko nije u stanju, neka spava, jer se tajni namaz udvostručuje","u odnosu na javni. Ustali smo i razišli se, a među nama je bio Alija ibn Ebu Talib, koji je stajao sa nama. Zatim je uzeo Alijinu ruku i rekao: Što se tebe tiče, ono što je meni dozvoljeno u mom mesdžidu dozvoljeno je i tebi, a ono što je meni zabranjeno zabranjeno je i tebi. Hamza ibn Abdul Muttalib mu je rekao: Allahov Poslaniče, ja sam tvoj amidža i bliži sam ti od Alije. Rekao je: Istinu si rekao, amidža. Tako mi Allaha, to nije ono što je on hteo, nego je to od Allaha, Uzvišenog i Veličanstvenog. Ta priča je već u osnovi laž, jer ju je preneo Bišr ibn Mihran, čiji je hadis odbačen i koji je","živeo u Basri među šijama. Što se tiče prenosioca Šerika, on je pouzdan, ali pravi veoma mnogo grešaka. Sedma predaja Ahmed ibn Meni je rekao: pričao nam je Hejsem, pričao nam je Hafs, od Harama ibn Osmana, od dvojice Džabirovih sinova, od Džabira, koji je rekao: Allahov Poslanik je došao dok smo ležali u mesdžidu, i udario nas svežim štapom koji je imao u ruci, rekavši: Zar spavate u mesdžidu? U mesdžidu se ne spava. Trgli smo se, a sa nama se trgnuo i Alija. Allahov Poslanik mu je rekao: Priđi, Alija, jer ono što je meni dozvoljeno u mesdžidu dozvoljeno je i tebi. Ta priča je laž. Prenosilac te priče jeste Haram ibn Osman, a to je prenosilac čiji","je hadis napušten. Zatim, priču pripisuje dvojici Džabirovih sinova, ali to pitanje ostaje nejasno. Šta stoji u šijskim knjigama Ovo su, dakle, predaje koje šije na svojim sajtovima navode kao dokaz, a mi smo na osnovu sunijskih knjiga pokazali njihovu slabost i krhkost. Što se, međutim, tiče šijskih knjiga, delo Vesailu š ši'a uvrstilo je ovu predaju sa senedom koji je po šijskim hadiskim načelima ispravan: Muhammed ibn el Hasan, svojim senedom, od Musaa ibn el Kasima, od Abdur Rahmana, od Muhammeda ibn Humrana, od Ebu Abdullaha, u hadisu, rekao je: Naši drugovi su preneli da je Allahov Poslanik rekao: Niko neka ne spava u mom mesdžidu i neka u njemu ne bude džunup. I rekao je: Allah mi je","objavio da uzmem čist mesdžid u kojem nikome nije dozvoljeno da bude džunup, osim meni, Aliji, Hasanu i Husejnu. Izvor: Vesailu š ši'a. Prema toj šijskoj predaji, dakle, oni sami dozvoljavaju Aliji, Hasanu i Husejnu da budu u stanju džunupluka u čistom Poslanikovom mesdžidu."]},{"slug":"Zasto-Omer-nije-izvrsio-kaznu-nad-optuzenim","chunks":["Predaja govori isključivo o optužbi, a ne o dokazanom delu. Optužba nije dokaz. Bez svedoka, tragova i dokaza sudija ne može izvršiti šerijatsku kaznu, nego mu preostaju dve mogućnosti: oslobađajuća presuda ili ta'zir. Kur'an u suri El Hudžurat izričito naređuje proveru vesti. Uz to, u predaji se nigde ne navodi da je optuženi bio ashab. Sadržaj primedbe Šije tvrde da su ashabi činili razvrat naroda Lutovog i da ih Omer ibn el Hattab nije kaznio. Kao dokaz navode sledeću predaju: Obavestio nas je Abdur Rezzak, od Ma'mera, od Zuhrija, od Urve, od Aiše, koja je rekla: Prvi koji je bio optužen za ružno delo, misleći na dela naroda Lutovog, bio je optužen u vreme Omera. Omer je naredio pojedinim kurejšijskim","mladićima da ne sede s njim. Odgovor na ovu primedbu Prvo predaja govori samo o optužbi Ovu predaju spominje Bejheki u svom delu Šuabul iman: Obavestio nas je Ebul Husejn ibn Bišran, obavestio nas je Ismail ibn Muhammed es Saffar, obavestio nas je Ahmed ibn Mensur, obavestio nas je Abdur Rezzak, obavestio nas je Ma'mer, od Zuhrija, od Urve, od Aiše, koja je rekla: Prvi koji je bio optužen za ružnu stvar, misleći na dela naroda Lutovog, bio je za to optužen u vreme Omera, pa je Omer naredio pojedinim kurejšijskim mladićima da ne sede s njim. U toj predaji se, međutim, ne navodi da je taj čovek počinio to delo. Predaja kaže da je za to bio optužen, pa","ne možemo biti sigurni da li je čovek to učinio ili nije. Optužba nije dokaz da je delo počinjeno. Kroz istoriju nalazimo mnoge čestite ljude koji su bili lažno optuženi, iako su bili nevini. Čak je i poslanik Jusuf bio lažno optužen. Puka optužba, dakle, ne znači da je čovek počinio to delo, jer ima mnogo nevinih ljudi kojima drugi zavide, pa protiv njih izmišljaju lažne optužbe. Reči Muhammeda Rešida Ride Muhammed Rešid Rida u Tefsirul menaru, 8/462, kaže: Bejheki prenosi od Aiše da je prvi koji je bio optužen za ružno delo, misleći na dela naroda Lutovog, bio jedan čovek u vreme Omera. Omer je naredio pojedinim kurejšijskim mladićima da ne sede s njim, dakle samo zbog optužbe. Zašto","Omer nije izvršio šerijatsku kaznu To objašnjava zašto Omer ibn el Hattab nije izvršio propisanu kaznu nad optuženim. Halifa Omer nije imao dovoljno dokaza i tragova, a nije poznavao ono što je skriveno. Budući da sudija ne poznaje skriveno, dužan je da ispita dokaze, tragove i svedočanstva koja potkrepljuju optužbu. Ako takvih tragova, dokaza i svedočanstava nema, sudija ne može nad optuženim izvršiti šerijatsku kaznu. Preostaju mu dve mogućnosti: da donese oslobađajuću presudu ili da odredi ta'zir, odnosno kaznu po sopstvenoj proceni, primerenu slučaju. Zato ćete naći da Časni Kur'an naređuje da se sačeka dok se ne uverimo u svedoke i dokaze: Sura El Hudžurat 49:6 O vi koji verujete, ako vam nekakav nepošten čovek donese kakvu vest, dobro je","proverite, da u neznanju nekome zlo ne učinite, pa da se zbog onoga što ste učinili pokajete. Drugo u predaji se ne kaže da je bio ashab U predaji se ne spominje da je optuženi bio ashab Poslanika ﷺ, niti se spominje da je to delo počinio sa nekim ashabom. Naprotiv, iz očiglednog smisla predaje proizlazi da je optuženi bio nepoznat čovek. Uz to, u vreme Omera ibn el Hattaba bilo je mnogo ljudi koji nisu bili ashabi. Nakon smrti Poslanika ﷺ nastupilo je doba tabiina, sa različitim stepenima čestitosti. Bilo je i mladića koji nisu bili ashabi. Treće zašto je Omer zabranio mladićima da sede s njim Omer ibn el Hattab je to učinio iz predostrožnosti, da bi sprečio","svaki dodir između optuženog i drugih. Omer je to učinio i zato da se ne bi otvorila vrata ogovaranju. Jer, kada bi ljudi videli nekoga da ulazi u kuću tog optuženog čoveka, mogli bi pomisliti da je ušao radi nemoralnog dela, pa bi se širile glasine i optužbe, čime bi ugled onoga ko je ušao u kuću optuženog ili sedeo s njim mogao biti okaljan. Nedžmudin el Gazzi u svom delu, 5/509, kaže: Bejheki prenosi od Aiše, radijallahu anha: Prvi koji je bio optužen za ružnu stvar, misleći na dela naroda Lutovog, bio je za to optužen u vreme Omera, pa je Omer naredio pojedinim kurejšijskim mladićima da ne sede s njim. Ovaj hadis ukazuje na opreznost u pogledu sedenja","sa mladićem, naročito onim koji je optužen. Četvrto zašto baš kurejšijskim mladićima Čini se da se ta priča dogodila u plemenu Kurejš, pa je Omer stvar uputio upravo njima, budući da je bio vladar Medine, Meke i drugih gradova. Peto zašto ga Omer nije prognao kao Nasra ibn Hadždžadža Pod pretpostavkom da je priča o Nasru ibn Hadždžadžu tačna i pouzdana, u njoj se navodi da se jedna žena zanela Nasrovom lepotom, pa je halifa Omer na svaki način pokušavao da spreči da ga ona vidi, kako ne bi bila iskušana. Kada Omerovi pokušaji nisu uspeli, prognao je tog čoveka iz Medine. Što se tiče priče o čoveku koji je bio optužen, da ga je Omer prognao, osnovni problem bi","ostao, jer bi optuženi otišao u drugu zemlju i tamo se izmešao sa njenim stanovnicima. Zato je Omer uvideo da je najbolje rešenje sprečiti kurejšijske mladiće da sede s njim. Šesto zašto su pojedini imami prezirali dugo gledanje u lepog mladića Odgovor je jednostavno taj što su islamski učenjaci želeli da spreče one slaba srca da skliznu u ponor polne izopačenosti, jer ima ljudi čije se strasti pobude kada pogledaju lepo dete, pa ga otmu i nad njim počine nemoralno delo. Zato su islamski učenjaci onima slaba srca zabranili da predugo gledaju u bilo kojeg lepog mladića, da ne bi bili njime iskušani."]},{"slug":"test-clanak","chunks":["test"]}];
